import React, { type ReactNode } from 'react'
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { UCSC_PRESET_LOCATIONS } from '@/app/lib/definitions'

// ── Leaflet / react-leaflet mocks ─────────────────────────────────────────────
// Leaflet accesses window/document — mock it entirely for jsdom.

type ClickHandler = (e: { latlng: { lat: number; lng: number } }) => void

let capturedMapClickHandler: ClickHandler | null = null

jest.mock('leaflet', () => {
  function IconCtor() { /* stub */ }
  IconCtor.Default = {
    prototype: {} as Record<string, unknown>,
    mergeOptions: jest.fn(),
  }
  return { Icon: IconCtor }
})

jest.mock('react-leaflet', () => ({
  MapContainer: ({ children }: { children: ReactNode }) => (
    <div data-testid="map-container">{children}</div>
  ),
  TileLayer: () => null,
  Marker: ({
    children,
    eventHandlers,
    position,
  }: {
    children?: ReactNode
    eventHandlers?: { click?: () => void }
    position: [number, number]
  }) => (
    <button
      data-testid="marker"
      data-lat={position[0]}
      data-lng={position[1]}
      onClick={eventHandlers?.click}
    >
      {children}
    </button>
  ),
  Popup: ({ children }: { children: ReactNode }) => <div>{children}</div>,
  useMapEvents: ({ click }: { click?: ClickHandler }) => {
    capturedMapClickHandler = click ?? null
    return null
  },
}))

// Import after mocks are set up
import LocationMapPicker from '@/app/components/location-map-picker'

const NOOP = () => undefined

describe('LocationMapPicker', () => {
  beforeEach(() => {
    capturedMapClickHandler = null
  })

  it('renders the map container', () => {
    render(<LocationMapPicker value={null} onChange={NOOP} />)
    expect(screen.getByTestId('map-container')).toBeInTheDocument()
  })

  it('renders a button for each preset UCSC location', () => {
    render(<LocationMapPicker value={null} onChange={NOOP} />)
    const markers = screen.getAllByTestId('marker')
    // One marker per preset (no selected-value marker since value is null)
    expect(markers.length).toBe(UCSC_PRESET_LOCATIONS.length)
  })

  it('calls onChange with the correct label and coordinates when a preset marker is clicked', async () => {
    const user = userEvent.setup()
    const handleChange = jest.fn()
    render(<LocationMapPicker value={null} onChange={handleChange} />)

    const firstPreset = UCSC_PRESET_LOCATIONS[0]
    const markers = screen.getAllByTestId('marker')
    await user.click(markers[0])

    expect(handleChange).toHaveBeenCalledWith({
      label: firstPreset.label,
      lat: firstPreset.lat,
      lng: firstPreset.lng,
    })
  })

  it('calls onChange with label "Other" when clicking a custom spot on the map', () => {
    const handleChange = jest.fn()
    render(<LocationMapPicker value={null} onChange={handleChange} />)

    capturedMapClickHandler?.({ latlng: { lat: 37.001, lng: -122.06 } })

    expect(handleChange).toHaveBeenCalledWith({
      label: 'Other',
      lat: 37.001,
      lng: -122.06,
    })
  })

  it('does not fire onChange when in readOnly mode and a map click occurs', () => {
    const handleChange = jest.fn()
    render(
      <LocationMapPicker
        value={{ lat: 36.9996, lng: -122.0579, label: 'McHenry Library' }}
        onChange={handleChange}
        readOnly
      />,
    )

    capturedMapClickHandler?.({ latlng: { lat: 37.001, lng: -122.06 } })
    expect(handleChange).not.toHaveBeenCalled()
  })

  it('displays a selected-location marker when value is provided', () => {
    render(
      <LocationMapPicker
        value={{ lat: 36.9996, lng: -122.0579, label: 'McHenry Library' }}
        onChange={NOOP}
      />,
    )
    // Preset markers + 1 selected marker
    const markers = screen.getAllByTestId('marker')
    expect(markers.length).toBe(UCSC_PRESET_LOCATIONS.length + 1)
  })
})

import { CreateItemSchema, UpdateItemSchema } from '@/app/lib/item-schemas'

const BASE_VALID = {
  type: 'lost' as const,
  title: 'Test item',
  description: 'A description',
  category: 'Electronics' as const,
  location: 'McHenry Library',
}

describe('CreateItemSchema — lat/lng fields', () => {
  it('accepts a valid lat/lng pair alongside required fields', () => {
    const result = CreateItemSchema.safeParse({
      ...BASE_VALID,
      lat: '36.9996',
      lng: '-122.0579',
    })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.lat).toBeCloseTo(36.9996)
      expect(result.data.lng).toBeCloseTo(-122.0579)
    }
  })

  it('accepts a submission with no lat/lng (both optional)', () => {
    const result = CreateItemSchema.safeParse(BASE_VALID)
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.lat).toBeUndefined()
      expect(result.data.lng).toBeUndefined()
    }
  })

  it('coerces an empty-string lat to undefined without error', () => {
    const result = CreateItemSchema.safeParse({ ...BASE_VALID, lat: '', lng: '' })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.lat).toBeUndefined()
      expect(result.data.lng).toBeUndefined()
    }
  })

  it('rejects a lat value above 90', () => {
    const result = CreateItemSchema.safeParse({ ...BASE_VALID, lat: '91', lng: '-122' })
    expect(result.success).toBe(false)
  })

  it('rejects a lat value below -90', () => {
    const result = CreateItemSchema.safeParse({ ...BASE_VALID, lat: '-91', lng: '-122' })
    expect(result.success).toBe(false)
  })

  it('rejects a lng value below -180', () => {
    const result = CreateItemSchema.safeParse({ ...BASE_VALID, lat: '37', lng: '-181' })
    expect(result.success).toBe(false)
  })

  it('rejects a lng value above 180', () => {
    const result = CreateItemSchema.safeParse({ ...BASE_VALID, lat: '37', lng: '181' })
    expect(result.success).toBe(false)
  })
})

describe('UpdateItemSchema', () => {
  it('accepts a valid edit payload', () => {
    const result = UpdateItemSchema.safeParse({ ...BASE_VALID, title: 'Updated name' })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.title).toBe('Updated name')
    }
  })

  it('rejects an empty title (all core fields stay required)', () => {
    const result = UpdateItemSchema.safeParse({ ...BASE_VALID, title: '' })
    expect(result.success).toBe(false)
  })

  it('rejects an unknown category', () => {
    const result = UpdateItemSchema.safeParse({ ...BASE_VALID, category: 'Spaceship' })
    expect(result.success).toBe(false)
  })
})

import { UpdateProfileSchema } from '@/app/lib/profile-schemas'

describe('UpdateProfileSchema', () => {
  it('accepts a valid display name', () => {
    const result = UpdateProfileSchema.safeParse({ display_name: 'Sammy Slug' })
    expect(result.success).toBe(true)
  })

  it('trims surrounding whitespace', () => {
    const result = UpdateProfileSchema.safeParse({ display_name: '  Sammy  ' })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.display_name).toBe('Sammy')
    }
  })

  it('rejects an empty display name', () => {
    const result = UpdateProfileSchema.safeParse({ display_name: '   ' })
    expect(result.success).toBe(false)
  })

  it('rejects a display name longer than 40 characters', () => {
    const result = UpdateProfileSchema.safeParse({ display_name: 'a'.repeat(41) })
    expect(result.success).toBe(false)
  })
})

'use client'

import { useActionState, useState } from 'react'
import Link from 'next/link'
import { toast } from 'sonner'
import { createItem } from '@/app/actions/items'
import type { CreateItemFormState } from '@/app/lib/item-schemas'
import { ITEM_CATEGORIES } from '@/app/lib/definitions'
import LocationMapPicker, {
  type MapLocation,
} from '@/app/components/location-map-picker-dynamic'

const INPUT_CLS =
  'rounded-xl border border-line-strong bg-surface-2 px-4 py-2.5 text-sm text-ink placeholder-muted outline-none transition focus:border-gold focus:ring-1 focus:ring-gold'

const SELECT_CLS =
  'rounded-xl border border-line-strong bg-surface-2 px-4 py-2.5 text-sm text-ink-soft outline-none focus:border-gold focus:ring-1 focus:ring-gold'

// Applied on top of INPUT_CLS / SELECT_CLS for any field that was filled in
// by the AI scan. The blue border lets the user spot which values they may
// want to double-check before posting.
const AI_HIGHLIGHT_CLS = 'border-claimed border-2'

interface CreateFormProps {
  initialType: 'lost' | 'found'
}

export default function CreateForm({ initialType }: CreateFormProps) {
  // useActionState wires the form to the createItem server action; on success
  // it redirects, so we only get a return value when there's an error.
  const [state, action, pending] = useActionState<CreateItemFormState, FormData>(
    createItem,
    undefined,
  )

  const [type, setType] = useState<'lost' | 'found'>(initialType)
  const [mapLocation, setMapLocation] = useState<MapLocation | null>(null)
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  // We track the file as both a controlled state (for preview) and a hidden
  // input ref so the FormData submitted to the server still includes it.

  // Controlled state for the AI-fillable fields. We keep the `name` attribute
  // on each input so FormData still picks them up on submit.
  const [title, setTitle] = useState('')
  const [category, setCategory] = useState('')
  const [description, setDescription] = useState('')

  // Tracks which fields were populated by the most recent AI scan so we can
  // highlight them. A field is removed from the set the moment the user
  // edits it manually.
  const [aiFilledFields, setAiFilledFields] = useState<Set<string>>(new Set())
  const [isScanning, setIsScanning] = useState(false)

  const backHref = type === 'found' ? '/found' : '/lost'

  // Surface server-level errors as toasts (per-field errors render inline below)
  if (state?.message) {
    toast.error(state.message)
  }

  /**
   * Remove a field from the AI-filled highlight set. Called whenever the
   * user manually edits the field — at that point the value is theirs, not
   * the model's, and the blue border should go away.
   */
  function clearAiFilled(field: string) {
    setAiFilledFields((prev) => {
      if (!prev.has(field)) return prev
      const next = new Set(prev)
      next.delete(field)
      return next
    })
  }

  /**
   * Read a File as a base64 string (no `data:` prefix). FileReader returns a
   * data URL, so we strip the prefix before sending the payload to the API.
   */
  function fileToBase64(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = () => {
        const result = reader.result
        if (typeof result !== 'string') {
          reject(new Error('Unexpected FileReader result'))
          return
        }
        // result looks like: data:image/png;base64,iVBORw0KG...
        const comma = result.indexOf(',')
        resolve(comma >= 0 ? result.slice(comma + 1) : result)
      }
      reader.onerror = () => reject(reader.error ?? new Error('FileReader failed'))
      reader.readAsDataURL(file)
    })
  }

  async function handleAiScan() {
    if (!selectedFile || isScanning) return
    setIsScanning(true)
    try {
      const base64 = await fileToBase64(selectedFile)
      const res = await fetch('/api/ai/scan-item', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image: base64, mimeType: selectedFile.type }),
      })

      if (!res.ok) {
        throw new Error(`Scan failed (${res.status})`)
      }

      const data: {
        title?: string
        category?: string
        description?: string
      } = await res.json()

      const filled = new Set<string>()
      if (typeof data.title === 'string' && data.title.length > 0) {
        setTitle(data.title)
        filled.add('title')
      }
      if (typeof data.category === 'string' && data.category.length > 0) {
        setCategory(data.category)
        filled.add('category')
      }
      if (typeof data.description === 'string' && data.description.length > 0) {
        setDescription(data.description)
        filled.add('description')
      }
      setAiFilledFields(filled)
    } catch {
      toast.error('AI scan failed — please fill in the fields manually')
    } finally {
      setIsScanning(false)
    }
  }

  const titleCls = `${INPUT_CLS}${aiFilledFields.has('title') ? ` ${AI_HIGHLIGHT_CLS}` : ''}`
  const categoryCls = `${SELECT_CLS}${aiFilledFields.has('category') ? ` ${AI_HIGHLIGHT_CLS}` : ''}`
  const descriptionCls = `resize-none ${INPUT_CLS}${
    aiFilledFields.has('description') ? ` ${AI_HIGHLIGHT_CLS}` : ''
  }`

  return (
    <div className="mx-auto w-full max-w-2xl px-4 py-10">
      {/* Page header */}
      <div className="mb-8">
        <Link
          href={backHref}
          className="mb-4 inline-flex items-center gap-1.5 text-sm text-muted transition-colors hover:text-ink"
        >
          ← Back
        </Link>
        <h1 className="text-3xl font-bold text-ink">Create a listing</h1>
        <p className="mt-1 text-sm text-muted">
          Help the UCSC community recover lost items.
        </p>
      </div>

      <form action={action} className="relative flex flex-col gap-5">
        {/* Disable all inputs while the AI scan is in flight. <fieldset disabled>
            does this in one line and is more bulletproof than wiring `disabled`
            into every input. */}
        <fieldset
          disabled={isScanning}
          className="contents"
        >
          {/* Hidden type field driven by the toggle below */}
          <input type="hidden" name="type" value={type} />

          {/* ── Section 1: What happened ── */}
          <div className="rounded-2xl border border-line bg-surface p-6">
            <h2 className="mb-1 text-sm font-semibold text-ink">What happened?</h2>
            <p className="mb-4 text-xs text-muted">
              Tell us whether you lost or found an item.
            </p>
            <div className="flex rounded-xl border border-line-strong bg-paper p-1">
              <button
                type="button"
                onClick={() => setType('lost')}
                className={`flex-1 rounded-lg py-2.5 text-sm font-semibold transition-colors ${
                  type === 'lost'
                    ? 'bg-lost-soft text-lost'
                    : 'text-muted hover:text-ink'
                }`}
              >
                I lost something
              </button>
              <button
                type="button"
                onClick={() => setType('found')}
                className={`flex-1 rounded-lg py-2.5 text-sm font-semibold transition-colors ${
                  type === 'found'
                    ? 'bg-found-soft text-found'
                    : 'text-muted hover:text-ink'
                }`}
              >
                I found something
              </button>
            </div>

            {type === 'found' && (
              <p className="mt-3 rounded-xl border border-gold/40 bg-gold-soft px-4 py-3 text-sm text-gold-ink">
                <span className="font-semibold">Tip:</span> The owner will contact you through
                SlugFound — you don&apos;t need to share personal contact info.
              </p>
            )}
          </div>

          {/* ── Section 2: About the item ── */}
          <div className="rounded-2xl border border-line bg-surface p-6">
            <h2 className="mb-1 text-sm font-semibold text-ink">About the item</h2>
            <p className="mb-5 text-xs text-muted">
              Describe it clearly so the right person can identify it.
            </p>

            <div className="flex flex-col gap-5">
              {/* Item name */}
              <div className="flex flex-col gap-1.5">
                <label htmlFor="title" className="text-sm font-medium text-ink-soft">
                  Item name
                </label>
                <input
                  id="title"
                  name="title"
                  type="text"
                  required
                  value={title}
                  onChange={(e) => {
                    setTitle(e.target.value)
                    clearAiFilled('title')
                  }}
                  placeholder={
                    type === 'lost'
                      ? 'e.g. AirPods Pro, Blue Jacket…'
                      : 'e.g. iPhone 14, Brown Wallet…'
                  }
                  className={titleCls}
                />
                {state?.errors?.title && (
                  <p className="text-xs text-lost">{state.errors.title[0]}</p>
                )}
              </div>

              {/* Category */}
              <div className="flex flex-col gap-1.5">
                <label htmlFor="category" className="text-sm font-medium text-ink-soft">
                  Category
                </label>
                <select
                  id="category"
                  name="category"
                  required
                  value={category}
                  onChange={(e) => {
                    setCategory(e.target.value)
                    clearAiFilled('category')
                  }}
                  className={categoryCls}
                >
                  <option value="" disabled>Select a category</option>
                  {ITEM_CATEGORIES.map((c) => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
                {state?.errors?.category && (
                  <p className="text-xs text-lost">{state.errors.category[0]}</p>
                )}
              </div>

              {/* Location map picker */}
              <div className="flex flex-col gap-1.5">
                <label className="text-sm font-medium text-ink-soft">
                  Location on campus
                </label>
                <p className="text-xs text-muted">
                  Click a preset marker or tap anywhere on the map to pin the exact spot.
                </p>

                {/* Hidden inputs carry map state into FormData for the server action */}
                <input type="hidden" name="location" value={mapLocation?.label ?? ''} />
                <input type="hidden" name="lat"      value={mapLocation?.lat  ?? ''} />
                <input type="hidden" name="lng"      value={mapLocation?.lng  ?? ''} />

                <LocationMapPicker value={mapLocation} onChange={setMapLocation} />

                {mapLocation && (
                  <p className="text-xs text-gold-ink">
                    📍 {mapLocation.label}
                    {mapLocation.label === 'Other' &&
                      ` (${mapLocation.lat.toFixed(5)}, ${mapLocation.lng.toFixed(5)})`}
                  </p>
                )}
                {state?.errors?.location && (
                  <p className="text-xs text-lost">{state.errors.location[0]}</p>
                )}
                {state?.errors?.lat && (
                  <p className="text-xs text-lost">{state.errors.lat[0]}</p>
                )}
                {state?.errors?.lng && (
                  <p className="text-xs text-lost">{state.errors.lng[0]}</p>
                )}
              </div>

              {/* Description */}
              <div className="flex flex-col gap-1.5">
                <label htmlFor="description" className="text-sm font-medium text-ink-soft">
                  Description
                </label>
                <textarea
                  id="description"
                  name="description"
                  rows={4}
                  required
                  value={description}
                  onChange={(e) => {
                    setDescription(e.target.value)
                    clearAiFilled('description')
                  }}
                  placeholder="Describe the item — color, brand, identifying marks, exact location…"
                  className={descriptionCls}
                />
                {state?.errors?.description && (
                  <p className="text-xs text-lost">{state.errors.description[0]}</p>
                )}
              </div>
            </div>
          </div>

          {/* ── Section 3: Photo ── */}
          <div className="rounded-2xl border border-line bg-surface p-6">
            <h2 className="mb-1 text-sm font-semibold text-ink">
              Photo <span className="font-normal text-muted">(optional)</span>
            </h2>
            <p className="mb-4 text-xs text-muted">
              A clear photo helps the owner identify their item instantly. Max 5 MB · JPG, PNG, WebP.
            </p>

            {selectedFile ? (
              <div className="flex items-center justify-between rounded-xl border border-line-strong bg-surface-2 px-4 py-3">
                <div className="flex items-center gap-3">
                  <span className="text-2xl">🖼️</span>
                  <div>
                    <p className="text-sm font-medium text-ink">{selectedFile.name}</p>
                    <p className="text-xs text-muted">
                      {(selectedFile.size / 1024).toFixed(0)} KB
                    </p>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => setSelectedFile(null)}
                  className="text-sm text-muted transition-colors hover:text-lost"
                >
                  Remove
                </button>
              </div>
            ) : (
              <label
                htmlFor="photo"
                className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-line-strong bg-paper py-10 text-center transition hover:border-gold hover:bg-surface-2"
              >
                <span className="text-3xl">📷</span>
                <span className="text-sm text-muted">Click to upload a photo</span>
                <span className="text-xs text-muted">PNG, JPG, WebP up to 5 MB</span>
              </label>
            )}

            {/* The actual file input — always rendered so its value is included in
                the FormData submission. We hide it when the preview card is shown. */}
            <input
              id="photo"
              name="photo"
              type="file"
              accept="image/jpeg,image/png,image/webp"
              className="sr-only"
              onChange={(e) => setSelectedFile(e.target.files?.[0] ?? null)}
            />

            {/* AI scan trigger — sits right under the drop zone and is disabled
                until a photo is selected. type="button" so it never submits. */}
            <button
              type="button"
              onClick={handleAiScan}
              disabled={!selectedFile || isScanning}
              className="mt-3 inline-flex items-center justify-center gap-2 rounded-full border border-claimed/40 bg-claimed-soft px-4 py-2 text-sm font-semibold text-claimed transition hover:border-claimed hover:bg-claimed-soft disabled:cursor-not-allowed disabled:opacity-50"
            >
              <span aria-hidden="true">✨</span>
              {isScanning ? 'Scanning…' : 'Scan with AI'}
            </button>

            {state?.errors?.photo && (
              <p className="mt-2 text-xs text-lost">{state.errors.photo[0]}</p>
            )}
          </div>

          {/* Submit */}
          <div className="flex gap-3 pt-1">
            <button
              type="submit"
              disabled={pending}
              className="flex flex-1 items-center justify-center gap-2 rounded-full bg-gold py-2.5 text-sm font-bold text-on-gold transition hover:bg-gold-bright disabled:opacity-50"
            >
              {pending ? (
                <>
                  <span className="h-4 w-4 animate-spin rounded-full border-2 border-ink border-t-transparent" />
                  Posting…
                </>
              ) : (
                type === 'lost' ? 'Post Lost Item' : 'Post Found Item'
              )}
            </button>
            <Link
              href={backHref}
              className="flex items-center justify-center rounded-full border border-line-strong px-5 text-sm font-medium text-muted transition hover:border-gold hover:text-ink"
            >
              Cancel
            </Link>
          </div>
        </fieldset>

        {/* Scanning overlay — absolutely positioned over the form. We only
            mount it while scanning so it doesn't intercept clicks otherwise. */}
        {isScanning && (
          <div className="absolute inset-0 z-10 flex items-center justify-center rounded-2xl bg-paper/80 backdrop-blur-sm">
            <div className="flex flex-col items-center gap-3 rounded-2xl border border-line bg-surface px-8 py-6 shadow-2xl">
              <span className="h-8 w-8 animate-spin rounded-full border-2 border-claimed border-t-transparent" />
              <p className="text-sm font-medium text-ink">Analyzing your photo…</p>
            </div>
          </div>
        )}
      </form>
    </div>
  )
}

import CreateForm from './create-form'

type PageProps = {
  // In Next.js 16, searchParams is a Promise — it must be awaited.
  // This page is a server component so it can await it, then passes
  // the resolved value down to the client component as a plain prop.
  searchParams: Promise<{ type?: string }>
}

export default async function CreatePage({ searchParams }: PageProps) {
  const { type } = await searchParams

  // Default to 'lost'. Any value other than 'found' is treated as 'lost'
  // so the form never starts in an undefined state.
  const initialType: 'lost' | 'found' = type === 'found' ? 'found' : 'lost'

  return <CreateForm initialType={initialType} />
}

'use client'

/**
 * Edit listing form (US 4.2).
 *
 * Pre-populated from the existing item. Mirrors the create form's fields and
 * styling (minus the AI scan). Submitting calls the `updateItem` server action
 * bound to this item's id; the Delete button opens a confirmation modal wired
 * to `deleteItem`.
 */

import { useActionState, useState, useTransition } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { updateItem, deleteItem } from '@/app/actions/items'
import type { UpdateItemFormState } from '@/app/lib/item-schemas'
import { ITEM_CATEGORIES } from '@/app/lib/definitions'
import type { Item } from '@/app/lib/definitions'
import LocationMapPicker, {
  type MapLocation,
} from '@/app/components/location-map-picker-dynamic'

const INPUT_CLS =
  'rounded-xl border border-line-strong bg-surface-2 px-4 py-2.5 text-sm text-ink placeholder-muted outline-none transition focus:border-gold focus:ring-1 focus:ring-gold'

const SELECT_CLS =
  'rounded-xl border border-line-strong bg-surface-2 px-4 py-2.5 text-sm text-ink-soft outline-none focus:border-gold focus:ring-1 focus:ring-gold'

interface EditFormProps {
  item: Item
}

export default function EditForm({ item }: EditFormProps) {
  const router = useRouter()

  const updateWithId = updateItem.bind(null, item.id)
  const [state, action, pending] = useActionState<UpdateItemFormState, FormData>(
    updateWithId,
    undefined,
  )

  const [type, setType] = useState<'lost' | 'found'>(item.type)
  const [title, setTitle] = useState(item.title)
  const [category, setCategory] = useState(item.category)
  const [description, setDescription] = useState(item.description)

  // Seed the map pin from existing coordinates when present.
  const [mapLocation, setMapLocation] = useState<MapLocation | null>(
    item.lat !== null && item.lng !== null
      ? { lat: item.lat, lng: item.lng, label: item.location }
      : null,
  )

  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [isDeleting, startDelete] = useTransition()

  const backHref = `/items/${item.id}`

  // Server-level errors surface as toasts; field errors render inline.
  if (state?.message) {
    toast.error(state.message)
  }

  function handleDelete() {
    startDelete(async () => {
      const result = await deleteItem(item.id)
      if (result.error) {
        toast.error(result.error)
        return
      }
      toast.success('Listing deleted')
      router.push(item.type === 'lost' ? '/lost' : '/found')
    })
  }

  return (
    <div className="mx-auto w-full max-w-2xl px-4 py-10">
      <div className="mb-8">
        <Link
          href={backHref}
          className="mb-4 inline-flex items-center gap-1.5 text-sm text-muted transition-colors hover:text-ink"
        >
          ← Back to listing
        </Link>
        <h1 className="text-3xl font-bold text-ink">Edit listing</h1>
        <p className="mt-1 text-sm text-muted">Update your post or remove it entirely.</p>
      </div>

      <form action={action} className="flex flex-col gap-5">
        {/* Lost / found toggle */}
        <div className="rounded-2xl border border-line bg-surface p-6">
          <h2 className="mb-4 text-sm font-semibold text-ink">Listing type</h2>
          <input type="hidden" name="type" value={type} />
          <div className="flex rounded-xl border border-line-strong bg-paper p-1">
            <button
              type="button"
              onClick={() => setType('lost')}
              className={`flex-1 rounded-lg py-2.5 text-sm font-semibold transition-colors ${
                type === 'lost' ? 'bg-lost-soft text-lost' : 'text-muted hover:text-ink'
              }`}
            >
              Lost
            </button>
            <button
              type="button"
              onClick={() => setType('found')}
              className={`flex-1 rounded-lg py-2.5 text-sm font-semibold transition-colors ${
                type === 'found'
                  ? 'bg-found-soft text-found'
                  : 'text-muted hover:text-ink'
              }`}
            >
              Found
            </button>
          </div>
        </div>

        {/* About the item */}
        <div className="rounded-2xl border border-line bg-surface p-6">
          <h2 className="mb-5 text-sm font-semibold text-ink">About the item</h2>

          <div className="flex flex-col gap-5">
            <div className="flex flex-col gap-1.5">
              <label htmlFor="title" className="text-sm font-medium text-ink-soft">
                Item name
              </label>
              <input
                id="title"
                name="title"
                type="text"
                required
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className={INPUT_CLS}
              />
              {state?.errors?.title && (
                <p className="text-xs text-lost">{state.errors.title[0]}</p>
              )}
            </div>

            <div className="flex flex-col gap-1.5">
              <label htmlFor="category" className="text-sm font-medium text-ink-soft">
                Category
              </label>
              <select
                id="category"
                name="category"
                required
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className={SELECT_CLS}
              >
                <option value="" disabled>
                  Select a category
                </option>
                {ITEM_CATEGORIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
              {state?.errors?.category && (
                <p className="text-xs text-lost">{state.errors.category[0]}</p>
              )}
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-sm font-medium text-ink-soft">Location on campus</label>
              <p className="text-xs text-muted">
                Click a preset marker or tap the map to move the pin.
              </p>

              {/* Hidden inputs carry map state; fall back to the original values
                  when the map isn't touched so existing data is preserved. */}
              <input
                type="hidden"
                name="location"
                value={mapLocation?.label ?? item.location}
              />
              <input type="hidden" name="lat" value={mapLocation?.lat ?? item.lat ?? ''} />
              <input type="hidden" name="lng" value={mapLocation?.lng ?? item.lng ?? ''} />

              <LocationMapPicker value={mapLocation} onChange={setMapLocation} />

              {mapLocation && (
                <p className="text-xs text-gold-ink">
                  📍 {mapLocation.label}
                  {mapLocation.label === 'Other' &&
                    ` (${mapLocation.lat.toFixed(5)}, ${mapLocation.lng.toFixed(5)})`}
                </p>
              )}
              {state?.errors?.location && (
                <p className="text-xs text-lost">{state.errors.location[0]}</p>
              )}
            </div>

            <div className="flex flex-col gap-1.5">
              <label htmlFor="description" className="text-sm font-medium text-ink-soft">
                Description
              </label>
              <textarea
                id="description"
                name="description"
                rows={4}
                required
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className={`resize-none ${INPUT_CLS}`}
              />
              {state?.errors?.description && (
                <p className="text-xs text-lost">{state.errors.description[0]}</p>
              )}
            </div>
          </div>
        </div>

        {/* Photo */}
        <div className="rounded-2xl border border-line bg-surface p-6">
          <h2 className="mb-1 text-sm font-semibold text-ink">
            Photo <span className="font-normal text-muted">(optional)</span>
          </h2>
          <p className="mb-4 text-xs text-muted">
            Upload a new photo to replace the current one. Max 5 MB · JPG, PNG, WebP.
          </p>

          {selectedFile ? (
            <div className="flex items-center justify-between rounded-xl border border-line-strong bg-surface-2 px-4 py-3">
              <div className="flex items-center gap-3">
                <span className="text-2xl">🖼️</span>
                <div>
                  <p className="text-sm font-medium text-ink">{selectedFile.name}</p>
                  <p className="text-xs text-muted">
                    {(selectedFile.size / 1024).toFixed(0)} KB · new
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setSelectedFile(null)}
                className="text-sm text-muted transition-colors hover:text-lost"
              >
                Remove
              </button>
            </div>
          ) : item.image_url ? (
            <div className="flex items-center gap-4">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={item.image_url}
                alt={item.title}
                className="h-16 w-16 rounded-xl border border-line-strong object-cover"
              />
              <label
                htmlFor="photo"
                className="cursor-pointer rounded-full border border-line-strong px-4 py-2 text-sm text-ink-soft transition hover:border-gold hover:text-ink"
              >
                Replace photo
              </label>
            </div>
          ) : (
            <label
              htmlFor="photo"
              className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-line-strong bg-paper py-10 text-center transition hover:border-gold hover:bg-surface-2"
            >
              <span className="text-3xl">📷</span>
              <span className="text-sm text-muted">Click to upload a photo</span>
              <span className="text-xs text-muted">PNG, JPG, WebP up to 5 MB</span>
            </label>
          )}

          <input
            id="photo"
            name="photo"
            type="file"
            accept="image/jpeg,image/png,image/webp"
            className="sr-only"
            onChange={(e) => setSelectedFile(e.target.files?.[0] ?? null)}
          />

          {state?.errors?.photo && (
            <p className="mt-2 text-xs text-lost">{state.errors.photo[0]}</p>
          )}
        </div>

        {/* Actions */}
        <div className="flex flex-wrap gap-3 pt-1">
          <button
            type="submit"
            disabled={pending}
            className="flex flex-1 items-center justify-center gap-2 rounded-full bg-gold py-2.5 text-sm font-bold text-on-gold transition hover:bg-gold-bright disabled:opacity-50"
          >
            {pending ? (
              <>
                <span className="h-4 w-4 animate-spin rounded-full border-2 border-ink border-t-transparent" />
                Saving…
              </>
            ) : (
              'Save changes'
            )}
          </button>
          <Link
            href={backHref}
            className="flex items-center justify-center rounded-full border border-line-strong px-5 text-sm font-medium text-muted transition hover:border-gold hover:text-ink"
          >
            Cancel
          </Link>
          <button
            type="button"
            onClick={() => setShowDeleteModal(true)}
            className="flex items-center justify-center rounded-full border border-lost/30 px-5 py-2.5 text-sm font-medium text-lost transition hover:border-lost/60 hover:text-lost"
          >
            Delete
          </button>
        </div>
      </form>

      {/* Delete confirmation modal */}
      {showDeleteModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
          <div className="w-full max-w-sm rounded-2xl border border-line bg-surface p-6 shadow-2xl">
            <h3 className="text-lg font-bold text-ink">Delete this listing?</h3>
            <p className="mt-2 text-sm text-muted">
              Are you sure? This cannot be undone.
            </p>
            <div className="mt-6 flex gap-3">
              <button
                type="button"
                disabled={isDeleting}
                onClick={handleDelete}
                className="flex flex-1 items-center justify-center gap-2 rounded-full bg-lost py-2.5 text-sm font-bold text-white transition hover:bg-lost/90 disabled:opacity-50"
              >
                {isDeleting ? 'Deleting…' : 'Delete'}
              </button>
              <button
                type="button"
                disabled={isDeleting}
                onClick={() => setShowDeleteModal(false)}
                className="flex-1 rounded-full border border-line-strong py-2.5 text-sm font-medium text-ink-soft transition hover:border-gold hover:text-ink disabled:opacity-50"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { notFound } from 'next/navigation'
import Link from 'next/link'
import { getItemById } from '@/app/lib/items'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import EditForm from './edit-form'

/**
 * Edit item page (/items/[id]/edit) — US 4.2.
 *
 * Owner-only. Non-owners hitting this URL directly get a 403 message, never the
 * form. A missing item id renders the segment's not-found page.
 */
type PageProps = {
  params: Promise<{ id: string }>
}

export default async function EditItemPage({ params }: PageProps) {
  const { id } = await params

  const item = await getItemById(id)
  if (!item) notFound()

  const supabase = await createSupabaseServerClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  // 403 guard — direct URL access by a non-owner shows a message, not the form.
  if (!user || user.id !== item.user_id) {
    return (
      <div className="mx-auto flex w-full max-w-2xl flex-col items-center justify-center gap-4 px-4 py-24 text-center">
        <span className="text-6xl">🔒</span>
        <h1 className="text-2xl font-bold text-ink">403 — Not your listing</h1>
        <p className="max-w-sm text-sm text-muted">
          You can only edit listings that you posted.
        </p>
        <Link
          href={`/items/${id}`}
          className="mt-2 rounded-full bg-gold px-5 py-2.5 text-sm font-bold text-on-gold transition hover:bg-gold-bright"
        >
          Back to listing
        </Link>
      </div>
    )
  }

  return <EditForm item={item} />
}

import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { getItemById } from '@/app/lib/items'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import ItemDetail from '@/app/components/item-detail'

/**
 * Canonical item detail page (/items/[id]) — US 4.1.
 *
 * The older /lost/[id] and /found/[id] routes now redirect here, so this is the
 * single source of truth for rendering an item. Ownership is resolved server-side
 * so the detail view can show owner-only actions (edit / status / delete).
 */
type PageProps = {
  // Next.js 16: params is a Promise — must be awaited.
  params: Promise<{ id: string }>
}

const META_DESCRIPTION_MAX = 155

/**
 * Dynamic <title>/<meta description> from the item itself (SEO requirement).
 * getItemById is React-cached, so this does not add a second DB round-trip.
 */
export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params
  const item = await getItemById(id)

  if (!item) {
    return { title: 'Item not found · SlugFound' }
  }

  const typeLabel = item.type === 'lost' ? 'Lost' : 'Found'
  const description =
    item.description.length > META_DESCRIPTION_MAX
      ? `${item.description.slice(0, META_DESCRIPTION_MAX - 1).trimEnd()}…`
      : item.description

  return {
    title: `${item.title} · ${typeLabel} · SlugFound`,
    description,
  }
}

export default async function ItemPage({ params }: PageProps) {
  const { id } = await params

  const item = await getItemById(id)
  if (!item) notFound()

  const supabase = await createSupabaseServerClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  const isOwner = user?.id === item.user_id

  return <ItemDetail item={item} isOwner={isOwner} />
}

import Sidebar from '@/app/components/sidebar'
import { UnreadProvider } from '@/app/lib/unread-context'
import { AuthProvider } from '@/app/lib/auth-context'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import { getUnreadCounts } from '@/app/lib/conversations'
import type { Profile } from '@/app/lib/definitions'

export default async function AppLayout({ children }: { children: React.ReactNode }) {
  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()

  let profile: Profile | null = null
  let initialUnreadCounts: Record<string, number> = {}

  if (user) {
    const [profileResult, unreadResult] = await Promise.all([
      supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single(),
      getUnreadCounts(user.id),
    ])
    profile = (profileResult.data as Profile | null) ?? null
    initialUnreadCounts = unreadResult
  }

  return (
    <AuthProvider initialUser={user} initialProfile={profile}>
      <UnreadProvider initialUnreadCounts={initialUnreadCounts}>
        <div className="flex min-h-screen bg-paper text-ink">
          <Sidebar />
          <div className="flex flex-1 flex-col min-w-0 pb-20 md:pb-0">{children}</div>
        </div>
      </UnreadProvider>
    </AuthProvider>
  )
}

import { redirect } from 'next/navigation'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import { listConversations, getConversationMessages } from '@/app/lib/conversations'
import MessagesView from '@/app/components/messages/messages-view'

type PageProps = {
  searchParams: Promise<{ c?: string }>
}

export default async function MessagesPage({ searchParams }: PageProps) {
  const { c: activeId = null } = await searchParams

  const supabase = await createSupabaseServerClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const conversations = await listConversations(user.id)

  const initialMessages: Record<string, readonly import('@/app/lib/definitions').ChatMessage[]> = {}
  if (activeId) {
    const msgs = await getConversationMessages(activeId)
    initialMessages[activeId] = msgs
  }

  return (
    <MessagesView
      conversations={conversations}
      activeId={activeId ?? null}
      currentUserId={user.id}
      initialMessages={initialMessages}
    />
  )
}

import { redirect } from 'next/navigation'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import { getUserItemStats, listUserItems } from '@/app/lib/items'
import type { Profile } from '@/app/lib/definitions'
import ProfileView from './profile-view'

/**
 * Profile page (US 2.6).
 *
 * Server component — fetches the signed-in user's profile, post stats, and
 * listings, then passes them to a client component for rendering with
 * interactive tabs.
 *
 * Middleware blocks unauthenticated access; the redirect below is a defense
 * in depth in case middleware is bypassed.
 */
export default async function ProfilePage() {
  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    redirect('/login')
  }

  const { data: profileData } = await supabase
    .from('profiles')
    .select('*')
    .eq('id', user.id)
    .single()

  const profile = (profileData as Profile | null) ?? null

  const [stats, listings] = await Promise.all([
    getUserItemStats(user.id),
    listUserItems(user.id, 50),
  ])

  return (
    <ProfileView
      profile={profile}
      email={user.email ?? ''}
      stats={stats}
      listings={listings}
    />
  )
}

'use client'

import { useState, useTransition } from 'react'
import Link from 'next/link'
import { toast } from 'sonner'
import { logout } from '@/app/actions/auth'
import { useAuth } from '@/app/lib/auth-context'
import { updateProfile, updateEmailNotifications } from '@/app/actions/profile'
import Badge, { type BadgeVariant } from '@/app/components/ui/badge'
import ThemeToggle from '@/app/components/theme-toggle'
import { initialFromName, timeAgo } from '@/app/lib/format'
import type { Profile, Item } from '@/app/lib/definitions'
import type { UserItemStats } from '@/app/lib/items'

const MAX_AVATAR_BYTES = 2 * 1024 * 1024
const ALLOWED_AVATAR_MIME = ['image/jpeg', 'image/png', 'image/webp']

type Tab = 'listings' | 'saved' | 'settings'

const COLLEGES = [
  'Cowell College',
  'Stevenson College',
  'Crown College',
  'Merrill College',
  'Kresge College',
  'Porter College',
  'Oakes College',
  'Rachel Carson College',
  'Nine College',
]

interface ProfileViewProps {
  profile: Profile | null
  email: string
  stats: UserItemStats
  listings: Item[]
}

/**
 * Renders the signed-in user's profile, stats, and listings.
 * Tab state is local — saved/settings are mock for Sprint 2 and don't persist.
 */
export default function ProfileView({ profile, email, stats, listings }: ProfileViewProps) {
  // Prefer the AuthContext profile so the header reflects edits immediately
  // after refreshProfile(); fall back to the server-provided prop on first paint.
  const { profile: ctxProfile, refreshProfile } = useAuth()
  const liveProfile = ctxProfile ?? profile

  const [activeTab, setActiveTab] = useState<Tab>('listings')
  const [isEditing, setIsEditing] = useState(false)
  const [avatarFile, setAvatarFile] = useState<File | null>(null)
  const [errors, setErrors] = useState<{ display_name?: string[]; avatar?: string[] }>()
  const [pending, startTransition] = useTransition()
  const [emailNotifications, setEmailNotifications] = useState(
    liveProfile?.email_notifications ?? true,
  )

  function handleToggleEmailNotifications() {
    const next = !emailNotifications
    setEmailNotifications(next) // optimistic
    startTransition(async () => {
      const result = await updateEmailNotifications(next)
      if (result.error) {
        setEmailNotifications(!next) // revert on failure
        toast.error(result.error)
      } else {
        toast.success(next ? 'Email notifications on' : 'Email notifications off')
      }
    })
  }

  // Handle submit via a transition so success/error handling (and the state
  // updates that close the form) live in an event callback, not an effect.
  function handleProfileSubmit(formData: FormData) {
    startTransition(async () => {
      const result = await updateProfile(undefined, formData)
      if (result?.success) {
        toast.success('Profile updated')
        await refreshProfile()
        setIsEditing(false)
        setAvatarFile(null)
        setErrors(undefined)
      } else if (result?.errors) {
        setErrors(result.errors)
      } else if (result?.message) {
        toast.error(result.message)
      }
    })
  }

  const displayName = liveProfile?.display_name ?? email.split('@')[0]
  const initial = initialFromName(displayName)
  const avatarUrl = liveProfile?.avatar_url ?? null
  const memberSince = liveProfile?.created_at
    ? new Date(liveProfile.created_at).toLocaleDateString('en-US', {
        month: 'long',
        year: 'numeric',
      })
    : 'recently'

  function handleAvatarSelect(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0] ?? null
    if (file && file.size > MAX_AVATAR_BYTES) {
      toast.error('Image must be 2 MB or smaller')
      e.target.value = ''
      return
    }
    if (file && !ALLOWED_AVATAR_MIME.includes(file.type)) {
      toast.error('Image must be JPG, PNG, or WebP')
      e.target.value = ''
      return
    }
    setAvatarFile(file)
  }

  const statCards = [
    { label: 'Posts', value: stats.totalPosts.toString() },
    { label: 'Reunited', value: stats.reunited.toString(), accent: true },
    { label: 'Active', value: stats.active.toString() },
  ]

  return (
    <div className="mx-auto w-full max-w-4xl px-4 py-10">
      {/* Profile header */}
      <div className="mb-10 flex flex-col items-start gap-6 sm:flex-row sm:items-center">
        {avatarUrl ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={avatarUrl}
            alt={displayName}
            className="h-20 w-20 rounded-full object-cover"
          />
        ) : (
          <div className="flex h-20 w-20 items-center justify-center rounded-full bg-gold text-3xl font-bold text-on-gold">
            {initial}
          </div>
        )}
        <div className="flex-1">
          <h1 className="text-2xl font-bold text-ink">{displayName}</h1>
          <p className="text-sm text-muted">{email}</p>
          <p className="mt-1 text-xs text-muted">
            Member since {memberSince}
            {liveProfile?.college ? ` · ${liveProfile.college}` : ''}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <ThemeToggle />
          <button
            type="button"
            onClick={() => setIsEditing((v) => !v)}
            className="rounded-full border border-line-strong px-4 py-2 text-sm font-medium text-ink-soft transition hover:border-gold hover:text-ink"
          >
            {isEditing ? 'Close' : 'Edit profile'}
          </button>
        </div>
      </div>

      {/* Inline edit form (US 4.5) */}
      {isEditing && (
        <form
          action={handleProfileSubmit}
          className="mb-10 flex flex-col gap-5 rounded-2xl border border-line bg-surface p-6"
        >
          <div className="flex flex-col gap-1.5">
            <label htmlFor="display_name" className="text-sm font-medium text-ink-soft">
              Display name
            </label>
            <input
              id="display_name"
              name="display_name"
              type="text"
              required
              maxLength={40}
              defaultValue={liveProfile?.display_name ?? ''}
