/**
 * Sign-up form (US 2.1).
 *
 * Wired to the `signup` server action. Includes:
 *   - Real-time password strength indicator
 *   - Inline @ucsc.edu validation hint
 *   - Confirm-password mismatch detection
 *   - Server-side error rendering via useActionState()
 */

import { useActionState, useState } from 'react'
import Link from 'next/link'
import { signup } from '@/app/actions/auth'
import type { AuthFormState } from '@/app/lib/auth-schemas'

// ─── Password strength helpers ─────────────────────────────────────────────

interface StrengthInfo {
  score: 0 | 1 | 2 | 3 | 4
  label: string
  color: string
}

/** Cheap, deterministic strength scorer. Mirrors the regex rules in SignupFormSchema. */
function scorePassword(pw: string): StrengthInfo {
  let score = 0
  if (pw.length >= 8) score++
  if (/[A-Z]/.test(pw)) score++
  if (/[0-9]/.test(pw)) score++
  if (/[^A-Za-z0-9]/.test(pw) || pw.length >= 12) score++

  const map: Record<number, Omit<StrengthInfo, 'score'>> = {
    0: { label: 'Too short', color: 'bg-surface-2' },
    1: { label: 'Weak', color: 'bg-lost' },
    2: { label: 'Fair', color: 'bg-[#c98a2e]' },
    3: { label: 'Good', color: 'bg-gold' },
    4: { label: 'Strong', color: 'bg-found' },
  }
  return { score: score as StrengthInfo['score'], ...map[score] }
}

const INPUT_CLS =
  'rounded-xl border border-line-strong bg-surface-2 px-4 py-2.5 text-sm text-ink placeholder-muted outline-none transition focus:border-gold focus:ring-1 focus:ring-gold'

export default function SignupForm() {
  const [state, action, pending] = useActionState<AuthFormState, FormData>(signup, undefined)

  // Local mirrors of the password fields so we can show strength + match feedback
  // before the user submits. The server action also re-validates on submit.
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [email, setEmail] = useState('')

  const strength = scorePassword(password)
  const passwordsMatch = confirm.length > 0 && password === confirm
  const showEmailHint = email.length > 0 && !email.endsWith('@ucsc.edu')

  return (
    <form action={action} className="flex flex-col gap-4">
      {/* Display name */}
      <div className="flex flex-col gap-1.5">
        <label htmlFor="displayName" className="text-sm font-medium text-ink-soft">
          Full name
        </label>
        <input
          id="displayName"
          name="displayName"
          type="text"
          autoComplete="name"
          placeholder="Sam Slug"
          className={INPUT_CLS}
        />
        {state?.errors?.displayName && (
          <p className="text-xs text-lost">{state.errors.displayName[0]}</p>
        )}
      </div>

      {/* Email */}
      <div className="flex flex-col gap-1.5">
        <label htmlFor="email" className="text-sm font-medium text-ink-soft">
          UCSC email
        </label>
        <input
          id="email"
          name="email"
          type="email"
          autoComplete="email"
          placeholder="slug@ucsc.edu"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className={INPUT_CLS}
        />
        {showEmailHint && (
          <p className="text-xs text-amber-400">
            Only <span className="font-mono">@ucsc.edu</span> emails can register.
          </p>
        )}
        {state?.errors?.email && (
          <p className="text-xs text-lost">{state.errors.email[0]}</p>
        )}
      </div>

      {/* Password + strength meter */}
      <div className="flex flex-col gap-1.5">
        <label htmlFor="password" className="text-sm font-medium text-ink-soft">
          Password
        </label>
        <input
          id="password"
          name="password"
          type="password"
          autoComplete="new-password"
          placeholder="••••••••"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className={INPUT_CLS}
        />

        {/* Strength meter — 4 bars that fill up as score increases */}
        {password.length > 0 && (
          <div className="mt-1 flex items-center gap-2">
            <div className="flex flex-1 gap-1">
              {[1, 2, 3, 4].map((bar) => (
                <div
                  key={bar}
                  className={`h-1 flex-1 rounded-full transition-colors ${
                    strength.score >= bar ? strength.color : 'bg-surface-2'
                  }`}
                />
              ))}
            </div>
            <span className="text-xs text-muted">{strength.label}</span>
          </div>
        )}

        <p className="text-xs text-muted">8+ chars, one uppercase, one number</p>

        {state?.errors?.password && (
          <p className="text-xs text-lost">{state.errors.password[0]}</p>
        )}
      </div>

      {/* Confirm password */}
      <div className="flex flex-col gap-1.5">
        <label htmlFor="confirm" className="text-sm font-medium text-ink-soft">
          Confirm password
        </label>
        <input
          id="confirm"
          name="confirm"
          type="password"
          autoComplete="new-password"
          placeholder="••••••••"
          value={confirm}
          onChange={(e) => setConfirm(e.target.value)}
          className={INPUT_CLS}
        />
        {confirm.length > 0 && !passwordsMatch && (
          <p className="text-xs text-lost">Passwords do not match.</p>
        )}
        {state?.errors?.confirm && (
          <p className="text-xs text-lost">{state.errors.confirm[0]}</p>
        )}
      </div>

      {/* Server-level error message (anything that isn't a per-field error) */}
      {state?.message && (
        <p className="rounded-xl border border-lost/25 bg-lost-soft px-4 py-3 text-sm text-lost">
          {state.message}
        </p>
      )}

      <button
        type="submit"
        disabled={pending}
        className="mt-1 flex h-11 items-center justify-center rounded-full bg-gold text-sm font-bold text-on-gold transition hover:bg-gold-bright disabled:opacity-50"
      >
        {pending ? 'Creating account…' : 'Create account'}
      </button>

      <p className="mt-2 text-center text-sm text-muted">
        Already have an account?{' '}
        <Link href="/login" className="font-medium text-gold-ink hover:text-gold-ink">
          Sign in
        </Link>
      </p>
    </form>
  )
}

'use server'

/**
 * Authentication server actions — Supabase-backed.
 *
 * Replaces the old JWT/bcrypt stub. Now delegates to Supabase Auth which
 * handles password hashing, session JWTs, refresh tokens, and email confirmation.
 *
 * Server actions used by:
 *   - Login form  → login()
 *   - Signup form → signup()
 *   - Sign out    → logout()
 *
 * NOTE: This file uses 'use server', which restricts exports to async functions
 * only. Schemas and types live in app/lib/auth-schemas.ts.
 */

import { redirect } from 'next/navigation'
import { revalidatePath } from 'next/cache'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import {
  LoginFormSchema,
  SignupFormSchema,
  type AuthFormState,
} from '@/app/lib/auth-schemas'

/**
 * Sign an existing user in. Called from the login form.
 * On success, redirects to /lost. On failure, returns a form state with errors.
 */
export async function login(
  _state: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const validated = LoginFormSchema.safeParse({
    email: formData.get('email'),
    password: formData.get('password'),
  })

  if (!validated.success) {
    return { errors: validated.error.flatten().fieldErrors }
  }

  const supabase = await createSupabaseServerClient()
  const { error } = await supabase.auth.signInWithPassword(validated.data)

  if (error) {
    // Map known Supabase error codes to user-friendly messages.
    if (error.message.toLowerCase().includes('invalid login')) {
      return { message: 'Invalid email or password.' }
    }
    if (error.message.toLowerCase().includes('email not confirmed')) {
      return { message: 'Please confirm your email before signing in.' }
    }
    return { message: error.message }
  }

  // Revalidate so server components re-fetch with the new session
  revalidatePath('/', 'layout')
  redirect('/lost')
}

/**
 * Register a new user. Called from the signup form.
 *
 * `display_name` is passed in user_metadata and read by the
 * `handle_new_user()` trigger in migration 0001 to populate the profiles row.
 */
export async function signup(
  _state: AuthFormState,
  formData: FormData,
): Promise<AuthFormState> {
  const validated = SignupFormSchema.safeParse({
    displayName: formData.get('displayName'),
    email: formData.get('email'),
    password: formData.get('password'),
    confirm: formData.get('confirm'),
  })

  if (!validated.success) {
    return { errors: validated.error.flatten().fieldErrors }
  }

  const supabase = await createSupabaseServerClient()
  const { error } = await supabase.auth.signUp({
    email: validated.data.email,
    password: validated.data.password,
    options: {
      data: { display_name: validated.data.displayName },
    },
  })

  if (error) {
    if (error.message.toLowerCase().includes('already registered')) {
      return { errors: { email: ['An account with this email already exists.'] } }
    }
    return { message: error.message }
  }

  revalidatePath('/', 'layout')
  redirect('/lost')
}

/**
 * Sign the current user out. Called by the sign-out button in Sidebar/Profile.
 * Clears the Supabase session cookie and redirects to /login.
 */
export async function logout() {
  const supabase = await createSupabaseServerClient()
  await supabase.auth.signOut()
  revalidatePath('/', 'layout')
  redirect('/login')
}

'use server'

/**
 * Server actions for item CRUD (US 2.4).
 *
 * Used by:
 *   - Create form  → createItem()
 *
 * Image uploads go to the `item-images` Storage bucket under a folder named
 * after the user's id (matches the RLS policy in migration 0003). The public
 * URL is stored on the item row.
 */

import { redirect } from 'next/navigation'
import { revalidatePath } from 'next/cache'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import { storagePathFromPublicUrl } from '@/app/lib/storage'
import {
  CreateItemSchema,
  UpdateItemSchema,
  type CreateItemFormState,
  type UpdateItemFormState,
} from '@/app/lib/item-schemas'

// ─── Constants ─────────────────────────────────────────────────────────────

const MAX_IMAGE_BYTES = 5 * 1024 * 1024 // 5 MB
const ALLOWED_MIME = ['image/jpeg', 'image/png', 'image/webp']

// ─── Action ────────────────────────────────────────────────────────────────

export async function createItem(
  _state: CreateItemFormState,
  formData: FormData,
): Promise<CreateItemFormState> {
  const supabase = await createSupabaseServerClient()

  // Auth check — middleware also enforces this, but we double-check so we can
  // fail with a clean error message instead of a blank crash.
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return { message: 'You must be signed in to create a listing.' }
  }

  const validated = CreateItemSchema.safeParse({
    type: formData.get('type'),
    title: formData.get('title'),
    description: formData.get('description'),
    category: formData.get('category'),
    location: formData.get('location'),
    lat: formData.get('lat'),
    lng: formData.get('lng'),
  })

  if (!validated.success) {
    return { errors: validated.error.flatten().fieldErrors }
  }

  // ── Optional image upload ───────────────────────────────────────────────
  const photo = formData.get('photo') as File | null
  let imageUrl: string | null = null

  if (photo && photo.size > 0) {
    if (photo.size > MAX_IMAGE_BYTES) {
      return { errors: { photo: ['Image must be 5 MB or smaller.'] } }
    }
    if (!ALLOWED_MIME.includes(photo.type)) {
      return { errors: { photo: ['Image must be JPG, PNG, or WebP.'] } }
    }

    // Path format MUST start with the user's id so the storage RLS policy
    // (storage.foldername(name)[1] = auth.uid()::text) accepts the upload.
    const ext = photo.name.split('.').pop() ?? 'bin'
    const path = `${user.id}/${crypto.randomUUID()}.${ext}`

    const { error: uploadError } = await supabase.storage
      .from('item-images')
      .upload(path, photo, { contentType: photo.type, upsert: false })

    if (uploadError) {
      return { errors: { photo: [`Image upload failed: ${uploadError.message}`] } }
    }

    const { data } = supabase.storage.from('item-images').getPublicUrl(path)
    imageUrl = data.publicUrl
  }

  // ── Insert ───────────────────────────────────────────────────────────────
  // RLS guarantees user_id matches auth.uid(), so we can safely set it client-side.
  const { error: insertError } = await supabase.from('items').insert({
    user_id: user.id,
    type: validated.data.type,
    title: validated.data.title,
    description: validated.data.description,
    category: validated.data.category,
    location: validated.data.location,
    image_url: imageUrl,
    lat: validated.data.lat ?? null,
    lng: validated.data.lng ?? null,
  })

  if (insertError) {
    return { message: `Could not save listing: ${insertError.message}` }
  }

  // Refresh the cached lost/found listings so the new item appears immediately
  revalidatePath('/lost')
  revalidatePath('/found')
  revalidatePath('/profile')

  redirect(validated.data.type === 'lost' ? '/lost' : '/found')
}

/**
 * Update the status of an item (active / claimed / resolved).
 * Only the item owner can call this — RLS enforces it server-side.
 *
 * Called from the item detail page when the owner clicks "Mark as resolved"
 * or similar. Returns `{ error }` on failure for the client to show a toast.
 */
export async function updateItemStatus(
  itemId: string,
  status: 'active' | 'claimed' | 'resolved',
): Promise<{ error?: string }> {
  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return { error: 'You must be signed in to update an item.' }
  }

  // RLS verifies user_id = auth.uid() — we don't need to check ownership here
  // because Postgres rejects the update for non-owners.
  const { error } = await supabase
    .from('items')
    .update({ status })
    .eq('id', itemId)

  if (error) {
    return { error: `Could not update status: ${error.message}` }
  }

  revalidatePath('/lost')
  revalidatePath('/found')
  revalidatePath('/profile')
  revalidatePath(`/items/${itemId}`)

  return {}
}

/**
 * Update an existing item (US 4.2).
 *
 * Bound to the item id via `updateItem.bind(null, itemId)` so it works with
 * useActionState. Ownership is enforced by RLS *and* re-checked here so we can
 * return a clean message. When a new photo is uploaded, the old Storage object
 * is removed after the row update succeeds (best-effort).
 */
export async function updateItem(
  itemId: string,
  _state: UpdateItemFormState,
  formData: FormData,
): Promise<UpdateItemFormState> {
  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return { message: 'You must be signed in to edit a listing.' }
  }

  const validated = UpdateItemSchema.safeParse({
    type: formData.get('type'),
    title: formData.get('title'),
    description: formData.get('description'),
    category: formData.get('category'),
    location: formData.get('location'),
    lat: formData.get('lat'),
    lng: formData.get('lng'),
  })

  if (!validated.success) {
    return { errors: validated.error.flatten().fieldErrors }
  }

  // Load the current row so we have the old image to swap out, and to fail
  // cleanly if the listing is missing or not ours.
  const { data: existing, error: fetchError } = await supabase
    .from('items')
    .select('image_url, user_id')
    .eq('id', itemId)
    .single()

  if (fetchError || !existing) {
    return { message: 'Listing not found.' }
  }
  if (existing.user_id !== user.id) {
    return { message: 'You can only edit your own listings.' }
  }

  // ── Optional photo replacement ──────────────────────────────────────────
  // `undefined` => keep current image; a string => replace it.
  const photo = formData.get('photo') as File | null
  let nextImageUrl: string | undefined

  if (photo && photo.size > 0) {
    if (photo.size > MAX_IMAGE_BYTES) {
      return { errors: { photo: ['Image must be 5 MB or smaller.'] } }
    }
    if (!ALLOWED_MIME.includes(photo.type)) {
      return { errors: { photo: ['Image must be JPG, PNG, or WebP.'] } }
    }

    const ext = photo.name.split('.').pop() ?? 'bin'
    const path = `${user.id}/${crypto.randomUUID()}.${ext}`

    const { error: uploadError } = await supabase.storage
      .from('item-images')
      .upload(path, photo, { contentType: photo.type, upsert: false })

    if (uploadError) {
      return { errors: { photo: [`Image upload failed: ${uploadError.message}`] } }
    }

    const { data } = supabase.storage.from('item-images').getPublicUrl(path)
    nextImageUrl = data.publicUrl
  }

  const { error: updateError } = await supabase
    .from('items')
    .update({
      type: validated.data.type,
      title: validated.data.title,
      description: validated.data.description,
      category: validated.data.category,
      location: validated.data.location,
      lat: validated.data.lat ?? null,
      lng: validated.data.lng ?? null,
      ...(nextImageUrl !== undefined ? { image_url: nextImageUrl } : {}),
    })
    .eq('id', itemId)

  if (updateError) {
    return { message: `Could not save changes: ${updateError.message}` }
  }

  // Remove the previous image now that the new URL is persisted. Best-effort —
  // a failed cleanup shouldn't block the edit.
  if (nextImageUrl !== undefined && existing.image_url) {
    const oldPath = storagePathFromPublicUrl(existing.image_url)
    if (oldPath) {
      await supabase.storage.from('item-images').remove([oldPath])
    }
  }

  revalidatePath(`/items/${itemId}`)
  revalidatePath('/lost')
  revalidatePath('/found')
  revalidatePath('/profile')

  redirect(`/items/${itemId}`)
}

/**
 * Delete an item and its Storage image (US 4.2).
 *
 * Returns `{ error }` on failure so the client can show a toast; navigation
 * after a successful delete is handled client-side. RLS restricts deletes to
 * the owner; we re-check here for a clean message.
 */
export async function deleteItem(itemId: string): Promise<{ error?: string }> {
  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return { error: 'You must be signed in to delete a listing.' }
  }

  const { data: existing } = await supabase
    .from('items')
    .select('image_url, user_id')
    .eq('id', itemId)
    .single()

  if (!existing) {
    return { error: 'Listing not found.' }
  }
  if (existing.user_id !== user.id) {
    return { error: 'You can only delete your own listings.' }
  }

  const { error } = await supabase.from('items').delete().eq('id', itemId)
  if (error) {
    return { error: `Could not delete listing: ${error.message}` }
  }

  if (existing.image_url) {
    const path = storagePathFromPublicUrl(existing.image_url)
    if (path) {
      await supabase.storage.from('item-images').remove([path])
    }
  }

  revalidatePath('/lost')
  revalidatePath('/found')
  revalidatePath('/profile')

  return {}
}

'use server'

import { z } from 'zod'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import { revalidatePath } from 'next/cache'
import { getConversationMessages } from '@/app/lib/conversations'
import type { ChatMessage } from '@/app/lib/definitions'

const FindOrCreateSchema = z.object({
  itemId: z.string().uuid(),
})

export async function findOrCreateConversation(
  itemId: string,
): Promise<{ conversationId: string } | { error: string }> {
  const parsed = FindOrCreateSchema.safeParse({ itemId })
  if (!parsed.success) {
    return { error: 'Invalid item ID.' }
  }

  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return { error: 'You must be signed in to send messages.' }
  }

  const { data: item, error: itemError } = await supabase
    .from('items')
    .select('id, user_id')
    .eq('id', parsed.data.itemId)
    .single()

  if (itemError || !item) {
    return { error: 'Item not found.' }
  }

  if (item.user_id === user.id) {
    return { error: 'You cannot message yourself about your own item.' }
  }

  const [userA, userB] =
    user.id < item.user_id ? [user.id, item.user_id] : [item.user_id, user.id]

  const { data: existing } = await supabase
    .from('conversations')
    .select('id')
    .eq('user_a', userA)
    .eq('user_b', userB)
    .eq('item_id', parsed.data.itemId)
    .single()

  if (existing) {
    return { conversationId: existing.id }
  }

  const { data: created, error: insertError } = await supabase
    .from('conversations')
    .insert({ user_a: userA, user_b: userB, item_id: parsed.data.itemId })
    .select('id')
    .single()

  if (insertError || !created) {
    return { error: `Could not create conversation: ${insertError?.message ?? 'unknown'}` }
  }

  revalidatePath('/messages')

  return { conversationId: created.id }
}

export async function markConversationRead(
  conversationId: string,
): Promise<{ error?: string }> {
  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return { error: 'Not signed in.' }
  }

  const { data: conv } = await supabase
    .from('conversations')
    .select('user_a, user_b')
    .eq('id', conversationId)
    .single()

  if (!conv) {
    return { error: 'Conversation not found.' }
  }

  const updateCol =
    conv.user_a === user.id ? 'user_a_last_read_at' : 'user_b_last_read_at'

  const { error } = await supabase
    .from('conversations')
    .update({ [updateCol]: new Date().toISOString() })
    .eq('id', conversationId)

  if (error) {
    return { error: `Could not mark as read: ${error.message}` }
  }

  return {}
}

export async function fetchConversationMessages(
