'use server'

/**
 * Report an item as inappropriate (US 4.6).
 *
 * Inserts a row into public.reports. The unique (item_id, reporter_id)
 * constraint means a second report from the same user surfaces as a friendly
 * "already reported" result rather than a duplicate row.
 */

import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import { ReportInputSchema, type ReportInput, type ReportResult } from '@/app/lib/reports-schemas'

export async function reportItem(input: ReportInput): Promise<ReportResult> {
  const parsed = ReportInputSchema.safeParse(input)
  if (!parsed.success) {
    return { error: 'Please choose a reason for the report.' }
  }

  const supabase = await createSupabaseServerClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) {
    return { error: 'You must be signed in to report an item.' }
  }

  const notes =
    parsed.data.notes && parsed.data.notes.length > 0 ? parsed.data.notes : null

  const { error } = await supabase.from('reports').insert({
    item_id: parsed.data.itemId,
    reporter_id: user.id,
    reason: parsed.data.reason,
    notes,
  })

  if (error) {
    // 23505 = unique_violation → this user already reported this item.
    if (error.code === '23505') {
      return { alreadyReported: true }
    }
    return { error: `Could not submit report: ${error.message}` }
  }

  return { success: true }
}

/**
 * AI photo scan endpoint — uses Groq vision API.
 *
 * Request body:  { image: string (base64, no data: prefix), mimeType: string }
 * Response:      { title, category, description }
 */

import Groq from 'groq-sdk'
import { ITEM_CATEGORIES } from '@/app/lib/definitions'

const TITLE_MAX = 80
const DESCRIPTION_MAX = 500

function clamp(value: unknown, max: number): string {
  if (typeof value !== 'string') return ''
  const trimmed = value.trim()
  return trimmed.length > max ? trimmed.slice(0, max) : trimmed
}

export async function POST(request: Request) {
  let body: { image?: string; mimeType?: string }
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body.' }, { status: 400 })
  }

  const { image, mimeType } = body
  if (!image) {
    return Response.json({ error: 'No image provided.' }, { status: 400 })
  }

  const prompt =
    `You are analyzing a photo of a found item for a university lost-and-found app. ` +
    `Respond ONLY with a valid JSON object and nothing else — no markdown, no backticks, no explanation. ` +
    `The JSON must have exactly these fields: { title: string (max ${TITLE_MAX} chars, concise name of the item), ` +
    `category: string (must be exactly one of: ${ITEM_CATEGORIES.map((c) => `"${c}"`).join(', ')}), ` +
    `description: string (max ${DESCRIPTION_MAX} chars, describe visible details like color, brand, condition, distinguishing features) }`

  try {
    const groq = new Groq({ apiKey: process.env.GROQ_API_KEY })

    const completion = await groq.chat.completions.create({
      model: 'meta-llama/llama-4-scout-17b-16e-instruct',
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'image_url',
              image_url: { url: `data:${mimeType ?? 'image/jpeg'};base64,${image}` },
            },
            { type: 'text', text: prompt },
          ],
        },
      ],
    })

    const raw = (completion.choices[0]?.message?.content ?? '').trim()

    // Strip accidental code-fence wrapping in case the model adds it anyway
    const fenceStripped = raw.startsWith('```')
      ? raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim()
      : raw
    const jsonMatch = fenceStripped.match(/\{[\s\S]*\}/)
    const cleaned = jsonMatch ? jsonMatch[0] : fenceStripped

    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(cleaned)
    } catch {
      return Response.json({ error: 'AI service unavailable' }, { status: 500 })
    }

    const categoryRaw = typeof parsed.category === 'string' ? parsed.category : ''
    const category = (ITEM_CATEGORIES as readonly string[]).includes(categoryRaw)
      ? categoryRaw
      : ITEM_CATEGORIES[0]

    return Response.json({
      title: clamp(parsed.title, TITLE_MAX),
      category,
      description: clamp(parsed.description, DESCRIPTION_MAX),
    })
  } catch (err) {
    console.error('[scan-item] Groq error:', err)
    return Response.json({ error: 'AI service unavailable' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createSupabaseAdminClient } from '@/app/lib/supabase/admin'
import { sendEmail } from '@/app/lib/email/resend'
import { renderNewMessageEmail, buildPreview } from '@/app/lib/email/new-message-template'

/**
 * New-message email notification webhook (US 4.4).
 *
 * Called by a Supabase Database Webhook on INSERT into public.messages. Resolves
 * the recipient, honours their opt-out, enforces a per-conversation rate limit,
 * and sends a branded email via Resend.
 *
 * Returns 200 even when it deliberately skips (opted out / rate limited) so the
 * webhook does not retry. Only transient failures return 5xx.
 */

const RATE_LIMIT_MINUTES = 10

const WebhookSchema = z.object({
  type: z.string(),
  table: z.string(),
  record: z.object({
    id: z.string(),
    conversation_id: z.string(),
    sender_id: z.string(),
    body: z.string(),
    created_at: z.string(),
  }),
})

function appUrl(): string {
  return process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000'
}

export async function POST(request: NextRequest) {
  // Fail closed: require the shared secret header to match.
  const secret = process.env.NOTIFY_WEBHOOK_SECRET
  if (!secret || request.headers.get('x-webhook-secret') !== secret) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  let payload: z.infer<typeof WebhookSchema>
  try {
    payload = WebhookSchema.parse(await request.json())
  } catch {
    return NextResponse.json({ error: 'Invalid payload' }, { status: 400 })
  }

  const msg = payload.record
  const supabase = createSupabaseAdminClient()

  // Conversation → the other participant is the recipient.
  const { data: conversation, error: convError } = await supabase
    .from('conversations')
    .select('user_a, user_b, item_id')
    .eq('id', msg.conversation_id)
    .single()
  if (convError || !conversation) {
    return NextResponse.json({ error: 'Conversation not found' }, { status: 404 })
  }

  const recipientId =
    conversation.user_a === msg.sender_id ? conversation.user_b : conversation.user_a

  const { data: recipient, error: recipError } = await supabase
    .from('profiles')
    .select('email, email_notifications, unsubscribe_token')
    .eq('id', recipientId)
    .single()
  if (recipError || !recipient) {
    return NextResponse.json({ error: 'Recipient not found' }, { status: 404 })
  }
  if (!recipient.email_notifications) {
    return NextResponse.json({ skipped: 'opted_out' })
  }

  // Rate limit: one email per (conversation, recipient) per window.
  const { data: logRow } = await supabase
    .from('notification_log')
    .select('last_notified_at')
    .eq('conversation_id', msg.conversation_id)
    .eq('recipient_id', recipientId)
    .single()
  if (logRow) {
    const elapsedMs = Date.now() - new Date(logRow.last_notified_at).getTime()
    if (elapsedMs < RATE_LIMIT_MINUTES * 60_000) {
      return NextResponse.json({ skipped: 'rate_limited' })
    }
  }

  const [{ data: sender }, { data: item }] = await Promise.all([
    supabase.from('profiles').select('display_name').eq('id', msg.sender_id).single(),
    supabase.from('items').select('title').eq('id', conversation.item_id).single(),
  ])

  const { subject, html, text } = renderNewMessageEmail({
    senderName: sender?.display_name ?? 'A SlugFound user',
    itemTitle: item?.title ?? 'an item',
    messagePreview: buildPreview(msg.body),
    conversationUrl: `${appUrl()}/messages?c=${msg.conversation_id}`,
    unsubscribeUrl: `${appUrl()}/api/notifications/unsubscribe?token=${recipient.unsubscribe_token}`,
  })

  try {
    await sendEmail({ to: recipient.email, subject, html, text })
  } catch (err) {
    console.error('[notifications/new-message] send failed:', err)
    return NextResponse.json({ error: 'Email send failed' }, { status: 502 })
  }

  await supabase.from('notification_log').upsert(
    {
      conversation_id: msg.conversation_id,
      recipient_id: recipientId,
      last_notified_at: new Date().toISOString(),
    },
    { onConflict: 'conversation_id,recipient_id' },
  )

  return NextResponse.json({ sent: true })
}

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createSupabaseAdminClient } from '@/app/lib/supabase/admin'

/**
 * One-click unsubscribe (US 4.4).
 *
 * Linked from the email footer: GET ?token=<unsubscribe_token> flips the
 * recipient's email_notifications to false. Uses the service role so it works
 * without a logged-in session (the token is the capability).
 */

const TokenSchema = z.string().uuid()

function htmlPage(title: string, body: string): Response {
  return new Response(
    `<!doctype html><html><head><meta name="viewport" content="width=device-width, initial-scale=1" /></head>` +
      `<body style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#09090b;color:#e4e4e7;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0;">` +
      `<div style="text-align:center;max-width:420px;padding:24px;">` +
      `<div style="font-size:22px;font-weight:700;margin-bottom:12px;"><span style="color:#facc15;">Slug</span><span style="color:#fff;">Found</span></div>` +
      `<h2 style="margin:0 0 8px;">${title}</h2><p style="color:#a1a1aa;">${body}</p></div></body></html>`,
    { headers: { 'Content-Type': 'text/html; charset=utf-8' } },
  )
}

export async function GET(request: NextRequest) {
  const token = request.nextUrl.searchParams.get('token') ?? ''
  const parsed = TokenSchema.safeParse(token)
  if (!parsed.success) {
    return htmlPage('Invalid link', 'This unsubscribe link is not valid.')
  }

  const supabase = createSupabaseAdminClient()
  const { error } = await supabase
    .from('profiles')
    .update({ email_notifications: false })
    .eq('unsubscribe_token', parsed.data)

  if (error) {
    return htmlPage('Something went wrong', 'Please try again later.')
  }

  return htmlPage(
    'Unsubscribed',
    'You will no longer receive email notifications for new messages. You can re-enable them anytime in your account settings.',
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { createSupabaseServerClient } from '@/app/lib/supabase/server'
import { compareImagesWithGemini } from '@/app/lib/gemini'
import type { Item } from '@/app/lib/definitions'

export type MatchStrength = 'High' | 'Medium' | 'Low'

export type PhotoSearchResult = Item & {
  similarity: number
  matchStrength: MatchStrength
}

const MAX_IMAGE_BYTES = 5 * 1024 * 1024
const ALLOWED_MIME = ['image/jpeg', 'image/png', 'image/webp']
const MIN_SIMILARITY = 0.4
const MAX_CANDIDATES = 30

function toMatchStrength(similarity: number): MatchStrength {
  if (similarity >= 0.75) return 'High'
  if (similarity >= 0.55) return 'Medium'
  return 'Low'
}

async function fetchImageAsBase64(
  url: string,
): Promise<{ base64: string; mimeType: string } | null> {
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(8000) })
    if (!res.ok) return null
    const mimeType = res.headers.get('content-type') ?? 'image/jpeg'
    const base64 = Buffer.from(await res.arrayBuffer()).toString('base64')
    return { base64, mimeType }
  } catch {
    return null
  }
}

export async function POST(request: NextRequest) {
  const supabase = await createSupabaseServerClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const formData = await request.formData()
  const photo = formData.get('photo') as File | null

  if (!photo || photo.size === 0) {
    return NextResponse.json({ error: 'No photo provided' }, { status: 400 })
  }
  if (photo.size > MAX_IMAGE_BYTES) {
    return NextResponse.json({ error: 'Image must be 5 MB or smaller' }, { status: 400 })
  }
  if (!ALLOWED_MIME.includes(photo.type)) {
    return NextResponse.json({ error: 'Image must be JPG, PNG, or WebP' }, { status: 400 })
  }

  const queryBase64 = Buffer.from(await photo.arrayBuffer()).toString('base64')

  // Only compare items that have photos — no image means nothing to visually compare
  const { data: items, error: dbError } = await supabase
    .from('items')
    .select('*, profile:profiles(id, display_name, avatar_url)')
    .eq('type', 'found')
    .eq('status', 'active')
    .not('image_url', 'is', null)
    .order('created_at', { ascending: false })
    .limit(MAX_CANDIDATES)

  if (dbError) {
    console.error('[photo-search] DB error:', dbError)
    return NextResponse.json({ error: 'Database error' }, { status: 500 })
  }

  if (!items || items.length === 0) {
    return NextResponse.json({ items: [] })
  }

  // Fetch all listing images in parallel
  const fetched = await Promise.all(
    (items as Item[]).map((item) => fetchImageAsBase64(item.image_url!)),
  )

  const candidates = (items as Item[])
    .map((item, i) => ({ item, img: fetched[i] }))
    .filter((c): c is { item: Item; img: { base64: string; mimeType: string } } => c.img !== null)

  if (candidates.length === 0) {
    return NextResponse.json({ items: [] })
  }

  let similarities: Map<string, number>
  try {
    similarities = await compareImagesWithGemini(
      queryBase64,
      photo.type,
      candidates.map((c) => ({ id: c.item.id, ...c.img })),
    )
  } catch (err) {
    console.error('[photo-search] Gemini compare error:', err)
    return NextResponse.json({ error: 'Could not analyze image' }, { status: 502 })
  }

  const results: PhotoSearchResult[] = candidates
    .map((c) => {
      const similarity = similarities.get(c.item.id) ?? 0
      return { ...c.item, similarity, matchStrength: toMatchStrength(similarity) }
    })
    .filter((r) => r.similarity >= MIN_SIMILARITY)
    .sort((a, b) => b.similarity - a.similarity)

  return NextResponse.json({ items: results })
}

