'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { toast } from 'sonner'
import type { Conversation, ChatMessage, MessageRow } from '@/app/lib/definitions'
import { useUnread } from '@/app/lib/unread-context'
import { useRealtimeMessages } from '@/app/lib/use-realtime-messages'
import { markConversationRead, fetchConversationMessages, sendConversationMessage } from '@/app/actions/messages'
import ConversationList from './conversation-list'
import MessageThread from './message-thread'
import EmptyThread from './empty-thread'

interface MessagesViewProps {
  conversations: readonly Conversation[]
  activeId: string | null
  currentUserId: string
  initialMessages: Record<string, readonly ChatMessage[]>
}

/**
 * Move a conversation to position 0 and update its preview/timestamp.
 * Returns a new immutable array — never mutates the input.
 *
 * Called when a message is sent or received so the most recently active
 * conversation always sorts to the top. NOT called on markConversationRead
 * (reading/clicking a conversation must not change ordering).
 */
function bubbleConversation(
  list: Conversation[],
  conversationId: string,
  preview: string,
  sentAt: string,
): Conversation[] {
  const idx = list.findIndex((c) => c.id === conversationId)
  if (idx === -1) return list

  const updated: Conversation = {
    ...list[idx],
    lastMessagePreview: preview,
    lastMessageAt: sentAt,
  }

  return [updated, ...list.slice(0, idx), ...list.slice(idx + 1)]
}

/** Read the `?c=` search param from the current URL. */
function getActiveIdFromUrl(): string | null {
  if (typeof window === 'undefined') return null
  return new URLSearchParams(window.location.search).get('c') || null
}

export default function MessagesView({
  conversations,
  activeId: serverActiveId,
  currentUserId,
  initialMessages,
}: MessagesViewProps) {
  const { unreadCounts, clearUnread, incrementUnread } = useUnread()

  // Stable Supabase client for the lifetime of this component — avoids
  // creating a new client (and potentially stale auth state) on every operation.
  const supabaseRef = useRef(createSupabaseBrowserClient())

  // ── Client-side active conversation ────────────────────────────────────────
  const [clientActiveId, setClientActiveId] = useState<string | null>(serverActiveId)

  const [sortedConversations, setSortedConversations] = useState<Conversation[]>(() =>
    [...conversations].sort(
      (a, b) =>
        new Date(b.lastMessageAt).getTime() - new Date(a.lastMessageAt).getTime(),
    ),
  )

  const [messagesByConversation, setMessagesByConversation] = useState<
    Record<string, readonly ChatMessage[]>
  >(() => ({ ...initialMessages }))

  // Ref (not state) so changes don't trigger extra effect reruns.
  const loadedConvsRef = useRef<Set<string>>(new Set(Object.keys(initialMessages)))

  const [isThreadLoading, setIsThreadLoading] = useState(false)

  const activeConversation = clientActiveId
    ? (sortedConversations.find((c) => c.id === clientActiveId) ?? null)
    : null

  // ── Select a conversation (client-side only) ──────────────────────────────
  const handleSelectConversation = useCallback((conversationId: string) => {
    setClientActiveId(conversationId)
    window.history.pushState(null, '', `/messages?c=${conversationId}`)
  }, [])

  // ── Go back to conversation list (client-side only) ───────────────────────
  const handleBack = useCallback(() => {
    setClientActiveId(null)
    window.history.pushState(null, '', '/messages')
  }, [])

  // ── Sync with browser back/forward buttons ────────────────────────────────
  useEffect(() => {
    function onPopState() {
      setClientActiveId(getActiveIdFromUrl())
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])

  // ── Fetch messages when switching to a conversation not yet loaded ────────
  useEffect(() => {
    if (!clientActiveId || loadedConvsRef.current.has(clientActiveId)) return

    // Mark immediately to prevent duplicate fetches on rapid navigation.
    loadedConvsRef.current.add(clientActiveId)
    setIsThreadLoading(true)

    fetchConversationMessages(clientActiveId).then((res) => {
      if ('error' in res && res.error) {
        toast.error(res.error)
        return
      }
      const messages = res.messages || []
      setMessagesByConversation((prev) => ({ ...prev, [clientActiveId]: messages }))
      setLoadedConversations((prev) => new Set(prev).add(clientActiveId))
    })
  }, [clientActiveId, loadedConversations])

  // Mark as read when the active conversation changes — does NOT affect ordering.
  useEffect(() => {
    if (clientActiveId) {
      clearUnread(clientActiveId)
      markConversationRead(clientActiveId)
    }
  }, [clientActiveId, clearUnread])

  const handleRealtimeMessage = useCallback(
    (msg: MessageRow) => {
      const chatMessage: ChatMessage = {
        id: msg.id,
        conversationId: msg.conversation_id,
        senderId: msg.sender_id,
        body: msg.body ?? '',
        imageUrl: msg.image_url ?? undefined,
        sentAt: msg.created_at,
      }

      setMessagesByConversation((prev) => ({
        ...prev,
        [msg.conversation_id]: [
          ...(prev[msg.conversation_id] ?? []),
          chatMessage,
        ],
      }))

      const preview = msg.body?.trim() || '📷 Photo'
      setSortedConversations((prev) =>
        bubbleConversation(prev, msg.conversation_id, preview, msg.created_at),
      )

      if (msg.conversation_id === clientActiveId) {
        markConversationRead(msg.conversation_id)
      } else {
        incrementUnread(msg.conversation_id)
      }
    },
    [clientActiveId, incrementUnread],
  )

  useRealtimeMessages({
    currentUserId,
    onNewMessage: handleRealtimeMessage,
  })

  async function handleSend(newMessage: ChatMessage) {
    // Optimistic update — add message to local thread immediately.
    setMessagesByConversation((prev) => ({
      ...prev,
      [newMessage.conversationId]: [
        ...(prev[newMessage.conversationId] ?? []),
        newMessage,
      ],
    }))

    const { error } = await sendConversationMessage(
      newMessage.conversationId,
      newMessage.body || null,
      newMessage.imageUrl ?? null
    )

    if (error) {
      // Rollback optimistic update on failure.
      setMessagesByConversation((prev) => ({
        ...prev,
        [newMessage.conversationId]: (prev[newMessage.conversationId] ?? []).filter(
          (m) => m.id !== newMessage.id,
        ),
      }))
      toast.error('Failed to send message.')
      return
    }

    const preview = newMessage.body.trim() || '📷 Photo'
    setSortedConversations((prev) =>
      bubbleConversation(prev, newMessage.conversationId, preview, newMessage.sentAt),
    )
  }

  const messages = clientActiveId ? (messagesByConversation[clientActiveId] ?? []) : []

  return (
    <div className="flex h-[calc(100dvh-80px)] overflow-hidden md:h-screen">
      <div className={`${clientActiveId ? 'hidden md:flex' : 'flex'} w-full md:w-auto`}>
        <ConversationList
          conversations={sortedConversations}
          activeId={clientActiveId}
          unreadCounts={unreadCounts}
          onSelect={handleSelectConversation}
        />
      </div>

      {activeConversation ? (
        <div className={`${clientActiveId ? 'flex' : 'hidden md:flex'} flex-1 flex-col overflow-hidden`}>
          <MessageThread
            conversation={activeConversation}
            messages={messages}
            currentUserId={currentUserId}
            onSend={handleSend}
            onBack={handleBack}
            isLoading={isThreadLoading}
          />
        </div>
      ) : (
        <EmptyThread />
      )}
    </div>
  )
}

'use client'

import { useRef, useState } from 'react'
import Link from 'next/link'
import ItemCard from '@/app/components/item-card'
import Badge from '@/app/components/ui/badge'
import type { PhotoSearchResult, MatchStrength } from '@/app/api/photo-search/route'

type Status = 'idle' | 'loading' | 'done' | 'error'

const MATCH_VARIANT: Record<MatchStrength, 'match-high' | 'match-medium' | 'match-low'> = {
  High: 'match-high',
  Medium: 'match-medium',
  Low: 'match-low',
}

export default function PhotoSearchForm() {
  const [status, setStatus] = useState<Status>('idle')
  const [results, setResults] = useState<PhotoSearchResult[]>([])
  const [errorMsg, setErrorMsg] = useState('')
  const [preview, setPreview] = useState<string | null>(null)
  const fileRef = useRef<HTMLInputElement>(null)

  function handleFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    const url = URL.createObjectURL(file)
    setPreview(url)
    setStatus('idle')
    setResults([])
    setErrorMsg('')
  }

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    const file = fileRef.current?.files?.[0]
    if (!file) return

    setStatus('loading')
    setResults([])
    setErrorMsg('')

    const fd = new FormData()
    fd.append('photo', file)

    try {
      const res = await fetch('/api/photo-search', { method: 'POST', body: fd })
      const data = await res.json()

      if (!res.ok) {
        setErrorMsg(data.error ?? 'Something went wrong. Please try again.')
        setStatus('error')
        return
      }

      setResults(data.items ?? [])
      setStatus('done')
    } catch {
      setErrorMsg('Network error. Please check your connection and try again.')
      setStatus('error')
    }
  }

  function reset() {
    setStatus('idle')
    setResults([])
    setErrorMsg('')
    setPreview(null)
    if (fileRef.current) fileRef.current.value = ''
  }

  return (
    <div>
      {/* Upload form */}
      <form onSubmit={handleSubmit} className="mb-8">
        <label
          htmlFor="photo-upload"
          className="flex cursor-pointer flex-col items-center justify-center gap-3 rounded-2xl border-2 border-dashed border-line-strong bg-surface p-10 text-center transition hover:border-gold hover:bg-surface-2"
        >
          {preview ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={preview}
              alt="Selected photo"
              className="mx-auto max-h-48 rounded-xl object-contain"
            />
          ) : (
            <>
              <span className="text-5xl">📷</span>
              <p className="text-sm font-medium text-ink-soft">
                Click to upload a photo of your lost item
              </p>
              <p className="text-xs text-muted">JPG, PNG, or WebP · max 5 MB</p>
            </>
          )}
          <input
            id="photo-upload"
            ref={fileRef}
            type="file"
            name="photo"
            accept="image/jpeg,image/png,image/webp"
            onChange={handleFileChange}
            className="sr-only"
          />
        </label>

        {preview && (
          <div className="mt-4 flex items-center gap-3">
            <button
              type="submit"
              disabled={status === 'loading'}
              className="flex-1 rounded-full bg-gold py-2.5 text-sm font-semibold text-on-gold transition hover:bg-gold-bright disabled:cursor-not-allowed disabled:opacity-60"
            >
              {status === 'loading' ? 'Analyzing image…' : 'Search by Photo'}
            </button>
            <button
              type="button"
              onClick={reset}
              className="rounded-full border border-line-strong px-4 py-2.5 text-sm text-ink-soft transition hover:border-gold hover:text-ink"
            >
              Clear
            </button>
          </div>
        )}
      </form>

      {/* Loading spinner */}
      {status === 'loading' && (
        <div className="flex flex-col items-center gap-3 py-16 text-center">
          <div className="h-8 w-8 animate-spin rounded-full border-2 border-gold border-t-transparent" />
          <p className="text-sm text-muted">Analyzing your photo with AI…</p>
        </div>
      )}

      {/* Error */}
      {status === 'error' && (
        <div className="rounded-xl border border-lost/25 bg-lost-soft px-5 py-4 text-sm text-lost">
          {errorMsg}
        </div>
      )}

      {/* Results */}
      {status === 'done' && (
        <>
          {results.length === 0 ? (
            <div className="flex flex-col items-center justify-center gap-3 rounded-2xl border border-dashed border-line-strong py-20 text-center">
              <span className="text-5xl">🔍</span>
              <p className="font-display text-lg font-semibold text-ink">No matching items found</p>
              <p className="text-sm text-muted">
                Try a clearer photo or browse all found items below
              </p>
              <Link
                href="/found"
                className="mt-2 rounded-full border border-line-strong px-4 py-2 text-sm text-ink-soft transition hover:border-gold hover:text-ink"
              >
                Browse all found items
              </Link>
            </div>
          ) : (
            <>
              <p className="mb-4 font-mono text-xs text-muted">
                {results.length} matching item{results.length !== 1 ? 's' : ''} found · ranked by
                similarity
              </p>
              <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                {results.map((item) => (
                  <div key={item.id} className="relative">
                    <ItemCard item={item} />
                    <span className="pointer-events-none absolute right-3 top-3">
                      <Badge variant={MATCH_VARIANT[item.matchStrength]}>
                        {item.matchStrength}
                      </Badge>
                    </span>
                  </div>
                ))}
              </div>
            </>
          )}
        </>
      )}
    </div>
  )
}

'use client'

/**
 * Overflow "⋯" menu with a Report action for an item detail page (US 4.6).
 *
 * Rendered only for non-owners. Opens a modal with a reason dropdown and an
 * optional notes field. A second report from the same user is reported back as
 * "already reported" (the DB unique constraint prevents duplicate rows).
 */

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { reportItem } from '@/app/actions/reports'
import { REPORT_REASONS, type ReportReason } from '@/app/lib/definitions'

const MAX_NOTES = 300

export default function ReportMenu({ itemId }: { itemId: string }) {
  const [menuOpen, setMenuOpen] = useState(false)
  const [modalOpen, setModalOpen] = useState(false)
  const [alreadyReported, setAlreadyReported] = useState(false)
  const [reason, setReason] = useState<ReportReason>('spam')
  const [notes, setNotes] = useState('')
  const [pending, startTransition] = useTransition()

  function openReportModal() {
    setMenuOpen(false)
    setAlreadyReported(false)
    setModalOpen(true)
  }

  function handleSubmit() {
    startTransition(async () => {
      const result = await reportItem({ itemId, reason, notes })
      if ('alreadyReported' in result) {
        setAlreadyReported(true)
        return
      }
      if ('error' in result) {
        toast.error(result.error)
        return
      }
      toast.success('Thanks — our team will review this.')
      setModalOpen(false)
      setNotes('')
    })
  }

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => setMenuOpen((v) => !v)}
        aria-label="More options"
        aria-haspopup="menu"
        className="flex h-9 w-9 items-center justify-center rounded-full border border-line-strong text-lg text-muted transition hover:border-gold hover:text-ink"
      >
        ⋯
      </button>

      {menuOpen && (
        <div
          role="menu"
          className="absolute right-0 z-20 mt-2 w-40 overflow-hidden rounded-xl border border-line bg-surface shadow-[0_14px_30px_-12px_rgba(27,36,53,0.3)]"
        >
          <button
            type="button"
            role="menuitem"
            onClick={openReportModal}
            className="block w-full px-4 py-2.5 text-left text-sm text-ink-soft transition hover:bg-surface-2 hover:text-ink"
          >
            🚩 Report
          </button>
        </div>
      )}

      {modalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-ink/40 p-4">
          <div className="w-full max-w-sm rounded-2xl border border-line bg-surface p-6 shadow-[0_24px_60px_-20px_rgba(27,36,53,0.45)]">
            {alreadyReported ? (
              <>
                <h3 className="font-display text-lg font-bold text-ink">Already reported</h3>
                <p className="mt-2 text-sm text-muted">
                  You&apos;ve already reported this listing. Our team will review it.
                </p>
                <button
                  type="button"
                  onClick={() => setModalOpen(false)}
                  className="mt-6 w-full rounded-full bg-gold py-2.5 text-sm font-bold text-on-gold transition hover:bg-gold-bright"
                >
                  Close
                </button>
              </>
            ) : (
              <>
                <h3 className="font-display text-lg font-bold text-ink">Report this listing</h3>
                <p className="mt-1 text-sm text-muted">
                  Help keep SlugFound safe. Tell us what&apos;s wrong.
                </p>

                <div className="mt-4 flex flex-col gap-1.5">
                  <label htmlFor="report-reason" className="text-sm font-medium text-ink-soft">
                    Reason
                  </label>
                  <select
                    id="report-reason"
                    value={reason}
                    onChange={(e) => setReason(e.target.value as ReportReason)}
                    className="rounded-xl border border-line bg-surface px-4 py-2.5 text-sm text-ink-soft outline-none focus:border-gold focus:ring-1 focus:ring-gold"
                  >
                    {REPORT_REASONS.map((r) => (
                      <option key={r.value} value={r.value}>
                        {r.label}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="mt-4 flex flex-col gap-1.5">
                  <label htmlFor="report-notes" className="text-sm font-medium text-ink-soft">
                    Notes <span className="font-normal text-muted">(optional)</span>
                  </label>
                  <textarea
                    id="report-notes"
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    rows={3}
                    maxLength={MAX_NOTES}
                    placeholder="Add any details…"
                    className="resize-none rounded-xl border border-line bg-surface px-4 py-2.5 text-sm text-ink placeholder-muted outline-none focus:border-gold focus:ring-1 focus:ring-gold"
                  />
                </div>

                <div className="mt-6 flex gap-3">
                  <button
                    type="button"
                    disabled={pending}
                    onClick={handleSubmit}
                    className="flex flex-1 items-center justify-center rounded-full bg-gold py-2.5 text-sm font-bold text-on-gold transition hover:bg-gold-bright disabled:opacity-50"
                  >
                    {pending ? 'Submitting…' : 'Submit report'}
                  </button>
                  <button
                    type="button"
                    disabled={pending}
                    onClick={() => setModalOpen(false)}
                    className="flex-1 rounded-full border border-line-strong py-2.5 text-sm font-medium text-ink-soft transition hover:border-gold hover:text-ink disabled:opacity-50"
                  >
                    Cancel
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

