'use client'

import { useState, useEffect, useCallback, type ReactNode } from 'react'
import { createPortal } from 'react-dom'

interface ImageOverlayProps {
  src: string
  alt: string
  trigger: ReactNode
}

export default function ImageOverlay({ src, alt, trigger }: ImageOverlayProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  const close = useCallback(() => setIsOpen(false), [])

  useEffect(() => {
    if (!isOpen) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close()
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [isOpen, close])

  const overlay = isOpen ? (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4"
      onClick={close}
      role="dialog"
      aria-modal="true"
      aria-label={alt}
    >
      {/* Clicking the image itself does not close the overlay */}
      <div className="relative" onClick={(e) => e.stopPropagation()}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={src}
          alt={alt}
          className="max-h-[90vh] max-w-[90vw] rounded-xl object-contain shadow-2xl"
        />
        <button
          type="button"
          onClick={close}
          aria-label="Close image"
          className="absolute -right-3 -top-3 flex h-7 w-7 items-center justify-center rounded-full bg-surface text-sm font-bold text-ink shadow-md transition hover:bg-surface-2"
        >
          ×
        </button>
      </div>
    </div>
  ) : null

  return (
    <>
      <button
        type="button"
        onClick={() => setIsOpen(true)}
        className="block w-full cursor-pointer focus:outline-none"
        aria-label={`View ${alt} fullscreen`}
      >
        {trigger}
      </button>
      {mounted && overlay && createPortal(overlay, document.body)}
    </>
  )
}

'use client'

/**
 * AuthContext — exposes the current Supabase user + profile to the entire
 * authenticated section of the app (US 2.2).
 *
 * Why we need this:
 *   The Sidebar, Profile page, and any client component that wants to know
 *   "who am I" needs synchronous access to user data. We could call
 *   supabase.auth.getUser() everywhere, but that's a network round trip
 *   on every component mount. Instead, fetch once in the provider, listen for
 *   auth state changes, and expose the result via React Context.
 *
 * Mounted in: app/(app)/layout.tsx — wraps everything authenticated.
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from 'react'
import type { User } from '@supabase/supabase-js'
import { createSupabaseBrowserClient } from './supabase/client'
import type { Profile } from './definitions'

interface AuthContextValue {
  user: User | null
  profile: Profile | null
  loading: boolean
  refreshProfile: () => Promise<void>
}

const AuthContext = createContext<AuthContextValue | null>(null)

interface AuthProviderProps {
  children: ReactNode
  // Initial values from the server so we don't render a flash of "logged out"
  // on first paint. Subsequent updates come from onAuthStateChange.
  initialUser: User | null
  initialProfile: Profile | null
}

export function AuthProvider({ children, initialUser, initialProfile }: AuthProviderProps) {
  const [user, setUser] = useState<User | null>(initialUser)
  const [profile, setProfile] = useState<Profile | null>(initialProfile)
  const [loading, setLoading] = useState(false)

  // useState lazy initializer — create the client once per mount, never recreate
  const [supabase] = useState(() => createSupabaseBrowserClient())

  /**
   * Fetch the profile row for the given user id. Used both inside the auth
   * state listener and when consumers want to force a refresh (e.g. after
   * editing display_name on the Profile page).
   */
  const fetchProfile = useCallback(
    async (userId: string): Promise<Profile | null> => {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single()

      if (error) {
        // Don't blow up — log and return null. The page will fall back to the
        // user's email until the profile row is reachable.
        console.error('Failed to fetch profile:', error.message)
        return null
      }
      return data as Profile
    },
    [supabase],
  )

  const refreshProfile = useCallback(async () => {
    if (!user) return
    const fresh = await fetchProfile(user.id)
    setProfile(fresh)
  }, [user, fetchProfile])

  useEffect(() => {
    /*
     * Subscribe to Supabase auth state changes. This fires on:
     *   - SIGNED_IN, SIGNED_OUT, TOKEN_REFRESHED, USER_UPDATED, INITIAL_SESSION
     * We re-fetch the profile row whenever the user changes.
     */
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (_event, session) => {
      const nextUser = session?.user ?? null
      setUser(nextUser)

      if (nextUser) {
        setLoading(true)
        const p = await fetchProfile(nextUser.id)
        setProfile(p)
        setLoading(false)
      } else {
        setProfile(null)
      }
    })

    return () => {
      subscription.unsubscribe()
    }
  }, [supabase, fetchProfile])

  return (
    <AuthContext.Provider value={{ user, profile, loading, refreshProfile }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used inside AuthProvider')
  return ctx
}

import 'server-only'
import { createSupabaseServerClient } from './supabase/server'
import { initialFromName } from './format'
import type {
  Conversation,
  ChatMessage,
  MessageUser,
  ConversationRow,
  MessageRow,
  Item,
  Profile,
  ItemType,
} from './definitions'

// ─── Mapping helpers ────────────────────────────────────────────────────────

export function toChatMessage(row: MessageRow): ChatMessage {
  return {
    id: row.id,
    conversationId: row.conversation_id,
    senderId: row.sender_id,
    body: row.body ?? '',
    imageUrl: row.image_url ?? undefined,
    sentAt: row.created_at,
  }
}

export function toConversation(
  row: ConversationRow,
  currentUserId: string,
  otherProfile: Pick<Profile, 'id' | 'display_name' | 'avatar_url' | 'college'>,
  item: Pick<Item, 'id' | 'title' | 'emoji' | 'type'>,
  lastMessage: { body: string | null; image_url: string | null; created_at: string } | null,
  unreadCount: number,
): Conversation {
  const otherUser: MessageUser = {
    id: otherProfile.id,
    name: otherProfile.display_name,
    initial: initialFromName(otherProfile.display_name),
    avatarUrl: otherProfile.avatar_url ?? undefined,
    college: otherProfile.college ?? undefined,
  }

  return {
    id: row.id,
    otherUser,
    itemId: item.id,
    itemTitle: item.title,
    itemEmoji: item.emoji ?? '📦',
    itemType: item.type as ItemType,
    lastMessagePreview: lastMessage?.body?.trim() || (lastMessage?.image_url ? '📷 Photo' : ''),
    lastMessageAt: lastMessage?.created_at ?? row.created_at,
    unreadCount,
  }
}

// ─── Queries ────────────────────────────────────────────────────────────────

type ConversationJoinRow = ConversationRow & {
  item: Pick<Item, 'id' | 'title' | 'emoji' | 'type'>
  profile_a: Pick<Profile, 'id' | 'display_name' | 'avatar_url' | 'college'>
  profile_b: Pick<Profile, 'id' | 'display_name' | 'avatar_url' | 'college'>
}

export async function listConversations(userId: string): Promise<Conversation[]> {
  const supabase = await createSupabaseServerClient()

  const { data: rows, error } = await supabase
    .from('conversations')
    .select(
      `*, item:items(id, title, emoji, type),
       profile_a:profiles!conversations_user_a_fkey(id, display_name, avatar_url, college),
       profile_b:profiles!conversations_user_b_fkey(id, display_name, avatar_url, college)`,
    )
    .or(`user_a.eq.${userId},user_b.eq.${userId}`)
    .order('created_at', { ascending: false })

  if (error) {
    console.error('[conversations.listConversations] failed:', error.message)
    return []
  }

  const conversationRows = (rows ?? []) as unknown as ConversationJoinRow[]

  const results = await Promise.all(
    conversationRows.map(async (row) => {
      const isUserA = row.user_a === userId
      const otherProfile = isUserA ? row.profile_b : row.profile_a
      const myLastReadAt = isUserA ? row.user_a_last_read_at : row.user_b_last_read_at

      const [lastMsgResult, unreadResult] = await Promise.all([
        supabase
          .from('messages')
          .select('body, image_url, created_at')
          .eq('conversation_id', row.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .single(),
        supabase
          .from('messages')
          .select('*', { count: 'exact', head: true })
          .eq('conversation_id', row.id)
          .neq('sender_id', userId)
          .gt('created_at', myLastReadAt),
      ])

      const lastMessage = lastMsgResult.data as { body: string | null; image_url: string | null; created_at: string } | null
      const unreadCount = unreadResult.count ?? 0

      return toConversation(row, userId, otherProfile, row.item, lastMessage, unreadCount)
    }),
  )

  // Sort by last message time (most recent first). This is done after hydration
  // because the sort key comes from the messages table, not the conversations table.
  // Sorting by conversations.updated_at was the previous bug — markConversationRead
  // updates that column, which displaced conversations on click.
  return results.sort(
    (a, b) => new Date(b.lastMessageAt).getTime() - new Date(a.lastMessageAt).getTime(),
  )
}

export async function getConversationMessages(conversationId: string): Promise<ChatMessage[]> {
  const supabase = await createSupabaseServerClient()

  const { data, error } = await supabase
    .from('messages')
    .select('*')
    .eq('conversation_id', conversationId)
    .order('created_at', { ascending: true })

  if (error) {
    console.error('[conversations.getConversationMessages] failed:', error.message)
    return []
  }

  return ((data ?? []) as MessageRow[]).map(toChatMessage)
}

export async function getUnreadCounts(userId: string): Promise<Record<string, number>> {
  const supabase = await createSupabaseServerClient()

  const { data: rows, error } = await supabase
    .from('conversations')
    .select('id, user_a, user_b, user_a_last_read_at, user_b_last_read_at')
    .or(`user_a.eq.${userId},user_b.eq.${userId}`)

  if (error) {
    console.error('[conversations.getUnreadCounts] failed:', error.message)
    return {}
  }

  const counts: Record<string, number> = {}

  await Promise.all(
    ((rows ?? []) as ConversationRow[]).map(async (row) => {
      const isUserA = row.user_a === userId
      const myLastReadAt = isUserA ? row.user_a_last_read_at : row.user_b_last_read_at

      const { count } = await supabase
        .from('messages')
        .select('*', { count: 'exact', head: true })
        .eq('conversation_id', row.id)
        .neq('sender_id', userId)
        .gt('created_at', myLastReadAt)

      counts[row.id] = count ?? 0
    }),
  )

  return counts
}

import 'server-only'
import { Resend } from 'resend'

/**
 * Thin wrapper around the Resend SDK (US 4.4). Reads RESEND_API_KEY at call time
 * so the rest of the app can be imported without the key being present.
 */
export interface SendEmailOptions {
  to: string
  subject: string
  html: string
  text: string
}

export async function sendEmail({ to, subject, html, text }: SendEmailOptions): Promise<void> {
  const apiKey = process.env.RESEND_API_KEY
  if (!apiKey) {
    throw new Error('RESEND_API_KEY not set')
  }

  // Defaults to Resend's shared test sender so the flow works before a custom
  // domain is verified. Override with EMAIL_FROM once a domain is set up.
  const from = process.env.EMAIL_FROM ?? 'SlugFound <onboarding@resend.dev>'

  const resend = new Resend(apiKey)
  const { error } = await resend.emails.send({ from, to, subject, html, text })

  if (error) {
    throw new Error(`Resend send failed: ${error.message}`)
  }
}

/**
 * Small formatting helpers used by listing cards and profile.
 */

/**
 * Render a relative time string from an ISO timestamp.
 * "2h ago", "3d ago", "just now". Falls back to a date for >30d.
 */
export function timeAgo(iso: string): string {
  const then = new Date(iso).getTime()
  const diffSec = Math.max(0, Math.floor((Date.now() - then) / 1000))

  if (diffSec < 60) return 'just now'
  const diffMin = Math.floor(diffSec / 60)
  if (diffMin < 60) return `${diffMin}m ago`
  const diffH = Math.floor(diffMin / 60)
  if (diffH < 24) return `${diffH}h ago`
  const diffD = Math.floor(diffH / 24)
  if (diffD < 7) return `${diffD}d ago`
  if (diffD < 30) return `${Math.floor(diffD / 7)}w ago`

  return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
}

/**
 * Format an ISO timestamp for message display.
 * Today → "10:12 AM", yesterday → "Yesterday", older → "May 12".
 */
export function formatMessageTime(iso: string): string {
  const date = new Date(iso)
  if (isNaN(date.getTime())) return ''

  const now = new Date()
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const yesterdayStart = new Date(todayStart.getTime() - 86_400_000)

  if (date.getTime() >= todayStart.getTime()) {
    return date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
  }
  if (date.getTime() >= yesterdayStart.getTime()) {
    return 'Yesterday'
  }
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
}

/** "Cowell College" → "C", "Sam Slug" → "S". Always uppercase. */
export function initialFromName(name: string | null | undefined): string {
  if (!name) return '?'
  const trimmed = name.trim()
  return (trimmed.charAt(0) || '?').toUpperCase()
}

const VISION_URL =
  'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent'
const EMBED_URL =
  'https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-2:embedContent'
const BATCH_EMBED_URL =
  'https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-2:batchEmbedContents'

export async function describeImage(base64: string, mimeType: string): Promise<string> {
  const apiKey = process.env.GEMINI_API_KEY
  if (!apiKey) throw new Error('GEMINI_API_KEY not set')

  const res = await fetch(`${VISION_URL}?key=${apiKey}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [
        {
          parts: [
            {
              text: 'Describe this item for a lost-and-found database. Be specific about: item type, color(s), brand (if visible), material, size, condition, and any distinctive features. Output only the description.',
            },
            { inline_data: { mime_type: mimeType, data: base64 } },
          ],
        },
      ],
    }),
    signal: AbortSignal.timeout(10000),
  })

  if (!res.ok) {
    const body = await res.json().catch(() => null)
    throw new Error(`Gemini vision ${res.status}: ${JSON.stringify(body)}`)
  }

  const body = await res.json()
  return body.candidates?.[0]?.content?.parts?.[0]?.text ?? ''
}

export async function embedText(text: string): Promise<number[]> {
  const apiKey = process.env.GEMINI_API_KEY
  if (!apiKey) throw new Error('GEMINI_API_KEY not set')

  const res = await fetch(`${EMBED_URL}?key=${apiKey}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'models/gemini-embedding-2',
      content: { parts: [{ text }] },
    }),
    signal: AbortSignal.timeout(10000),
  })

  if (!res.ok) {
    const body = await res.json().catch(() => null)
    throw new Error(`Gemini embed ${res.status}: ${JSON.stringify(body)}`)
  }

  const body = await res.json()
  return body.embedding?.values ?? []
}

/** Embeds multiple texts in a single API call. Returns embeddings in the same order. */
export async function batchEmbedTexts(texts: string[]): Promise<number[][]> {
  const apiKey = process.env.GEMINI_API_KEY
  if (!apiKey) throw new Error('GEMINI_API_KEY not set')

  const res = await fetch(`${BATCH_EMBED_URL}?key=${apiKey}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      requests: texts.map((text) => ({
        model: 'models/gemini-embedding-2',
        content: { parts: [{ text }] },
      })),
    }),
    signal: AbortSignal.timeout(30000),
  })

  if (!res.ok) {
    const body = await res.json().catch(() => null)
    throw new Error(`Gemini batch embed ${res.status}: ${JSON.stringify(body)}`)
  }

  const body = await res.json()
  return (body.embeddings as { values: number[] }[]).map((e) => e.values)
}

/**
 * Sends a query image + up to N candidate images to Gemini in one call.
 * Returns a map of candidate id → similarity score (0–1).
 */
export async function compareImagesWithGemini(
  queryBase64: string,
  queryMimeType: string,
  candidates: { id: string; base64: string; mimeType: string }[],
): Promise<Map<string, number>> {
  const apiKey = process.env.GEMINI_API_KEY
  if (!apiKey) throw new Error('GEMINI_API_KEY not set')

  const parts: object[] = [
    {
      text: `The first image is something someone lost and is searching for. I will show you ${candidates.length} found-item photos. For each, rate how visually similar it is to the first image — same item type, color, brand, and appearance. Return ONLY a JSON array with no extra text: [{"id":"<id>","similarity":<0.0-1.0>}]`,
    },
    { inline_data: { mime_type: queryMimeType, data: queryBase64 } },
    { text: 'Found item photos:' },
  ]

  for (const c of candidates) {
    parts.push({ text: `ID: ${c.id}` })
    parts.push({ inline_data: { mime_type: c.mimeType, data: c.base64 } })
  }

  const res = await fetch(`${VISION_URL}?key=${apiKey}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ parts }],
      generationConfig: { responseMimeType: 'application/json' },
    }),
    signal: AbortSignal.timeout(30000),
  })

  if (!res.ok) {
    const body = await res.json().catch(() => null)
    throw new Error(`Gemini compare ${res.status}: ${JSON.stringify(body)}`)
  }

  const body = await res.json()
  const text: string = body.candidates?.[0]?.content?.parts?.[0]?.text ?? '[]'
  const scores = JSON.parse(text) as { id: string; similarity: number }[]
  return new Map(scores.map((s) => [s.id, s.similarity]))
}

/**
 * Geo helpers for map view (US 4.7). Pure — no Leaflet or server dependencies,
 * so they're safe to import in client components and unit tests.
 */

import type { Item } from './definitions'

/** True when an item has both coordinates and can be placed on the map. */
export function hasCoordinates(item: Pick<Item, 'lat' | 'lng'>): boolean {
  return item.lat !== null && item.lng !== null
}

/** Items that can be shown on the map (those missing lat/lng are excluded). */
export function geotaggedItems<T extends Pick<Item, 'lat' | 'lng'>>(items: T[]): T[] {
  return items.filter(hasCoordinates)
}

/** UCSC campus center + default zoom for the listings map. */
export const UCSC_CENTER: readonly [number, number] = [36.9916, -122.0583]
export const UCSC_ZOOM = 15

/**
 * Zod schemas + form state types for item-related forms.
 *
 * Separate from app/actions/items.ts because 'use server' files can only
 * export async functions.
 */

import { z } from 'zod'
import { ITEM_CATEGORIES } from './definitions'

// FormData always serialises values as strings; empty string means "not set".
const toOptionalNumber = (v: unknown) =>
  v === '' || v === null || v === undefined ? undefined : Number(v)

// Shared field shape for both create and edit. Editing supports the same fields
// (title, description, category, location, photo) plus the lost/found type.
const itemFields = {
  type: z.enum(['lost', 'found']),
  title: z.string().trim().min(1, 'Title is required.').max(120),
  description: z.string().trim().min(1, 'Description is required.').max(1000),
  category: z.enum(ITEM_CATEGORIES, { message: 'Pick a category.' }),
  location: z.string().trim().min(1, 'Location is required.'),
  lat: z.preprocess(toOptionalNumber, z.number().min(-90).max(90).optional()),
  lng: z.preprocess(toOptionalNumber, z.number().min(-180).max(180).optional()),
}

export const CreateItemSchema = z.object(itemFields)

/** Same fields as create; the photo is handled separately and stays optional. */
export const UpdateItemSchema = z.object(itemFields)

export type CreateItemFormState =
  | {
      errors?: {
        title?: string[]
        description?: string[]
        category?: string[]
        location?: string[]
        lat?: string[]
        lng?: string[]
        photo?: string[]
      }
      message?: string
    }
  | undefined

/** Edit form returns the same error/message shape as create. */
export type UpdateItemFormState = CreateItemFormState

/**
 * Items repository — thin wrapper around Supabase queries on the `items` table.
 *
 * All callers should go through these functions instead of writing inline
 * supabase.from('items')... — keeps query logic in one place and makes it
 * trivial to swap implementations (e.g. add caching, batch joins, etc.).
 *
 * Server-only: imports the SSR client. Use these from server components and
 * server actions. Client components should call server actions, not these
 * directly.
 */

import 'server-only'
import { cache } from 'react'
import { createSupabaseServerClient } from './supabase/server'
import type { Item, ItemType } from './definitions'

export interface ListItemsOptions {
  type: ItemType
  search?: string
  category?: string  // 'All' or undefined → no filter
  location?: string  // empty string or undefined → no filter
  activeOnly?: boolean // when true, hide claimed/resolved items (US 4.3)
  limit?: number
}

/**
 * Fetch items of a given type (lost/found) with optional filters.
 *
 * Joins `profiles` so each item carries the poster's display_name + avatar
 * for rendering on listing cards.
 *
 * Ordering (US 4.3): active items first, then claimed/resolved. We rely on the
 * `item_status` enum being defined as ('active','claimed','resolved') — ascending
 * enum order is exactly active → claimed → resolved. Within each group, newest
 * first by created_at.
 */
export async function listItems(opts: ListItemsOptions): Promise<Item[]> {
  const { type, search, category, location, activeOnly, limit = 100 } = opts
  const supabase = await createSupabaseServerClient()

  let query = supabase
    .from('items')
    .select('*, profile:profiles(id, display_name, avatar_url)')
    .eq('type', type)
    .eq('reported_flag', false) // hide items flagged by 3+ reports (US 4.6)
    .order('status', { ascending: true })
    .order('created_at', { ascending: false })
    .limit(limit)

  if (activeOnly) {
    query = query.eq('status', 'active')
  }

  // Search across title + description using Postgres ILIKE (case-insensitive).
  // The `or` filter format is: 'col1.ilike.%term%,col2.ilike.%term%'.
  if (search && search.trim().length > 0) {
    const term = search.trim().replace(/[%_]/g, '\\$&') // escape ILIKE wildcards
    query = query.or(`title.ilike.%${term}%,description.ilike.%${term}%`)
  }

  if (category && category !== 'All') {
    query = query.eq('category', category)
  }

  if (location) {
    // Use ILIKE so 'Kresge' matches 'Kresge College'
    query = query.ilike('location', `%${location}%`)
  }

  const { data, error } = await query
  if (error) {
    console.error('[items.listItems] failed:', error.message)
    return []
  }
  return (data ?? []) as Item[]
}

/**
 * Fetch a single item by id (with poster profile joined).
 *
 * Wrapped in React `cache()` so that a detail page and its `generateMetadata`
 * (which both need the item) share a single Supabase query per request.
 * Supabase calls aren't auto-memoized the way `fetch` is, so we memoize here.
 */
export const getItemById = cache(async (id: string): Promise<Item | null> => {
  const supabase = await createSupabaseServerClient()
  const { data, error } = await supabase
    .from('items')
    .select('*, profile:profiles(id, display_name, avatar_url)')
    .eq('id', id)
    .single()

  if (error) {
    console.error('[items.getItemById] failed:', error.message)
    return null
  }
  return data as Item
})

/** Stats used by the Account page (US 2.6). */
export interface UserItemStats {
  totalPosts: number
  reunited: number  // claimed + resolved
  active: number
}

export async function getUserItemStats(userId: string): Promise<UserItemStats> {
  const supabase = await createSupabaseServerClient()

  // Use head: true with count: 'exact' to count rows without fetching them
  const [totalRes, activeRes, reunitedRes] = await Promise.all([
    supabase
      .from('items')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId),
    supabase
      .from('items')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId)
      .eq('status', 'active'),
    supabase
      .from('items')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId)
      .in('status', ['claimed', 'resolved']),
  ])

  return {
    totalPosts: totalRes.count ?? 0,
    active: activeRes.count ?? 0,
    reunited: reunitedRes.count ?? 0,
  }
}

/** Fetch items posted by a specific user (for Profile → My Listings). */
export async function listUserItems(userId: string, limit = 50): Promise<Item[]> {
  const supabase = await createSupabaseServerClient()
  const { data, error } = await supabase
    .from('items')
    .select('*')
    .eq('user_id', userId)
    .order('created_at', { ascending: false })
    .limit(limit)

  if (error) {
    console.error('[items.listUserItems] failed:', error.message)
    return []
  }
  return (data ?? []) as Item[]
}

/**
 * Supabase Storage URL helpers.
 *
 * Pure functions with no server/client dependencies, so they're safe to import
 * anywhere (server actions, client components, unit tests).
 */

/**
 * Extract the in-bucket object path from a Supabase public URL.
 *
 * Public URLs look like:
 *   https://<ref>.supabase.co/storage/v1/object/public/item-images/<uid>/<file>
 *
 * Returns "<uid>/<file>" (URL-decoded), or null if the URL doesn't point at the
 * given bucket. Used to delete the old image when swapping or removing a listing.
 */
export function storagePathFromPublicUrl(
  url: string | null | undefined,
  bucket = 'item-images',
): string | null {
  if (!url) return null
  const marker = `/storage/v1/object/public/${bucket}/`
  const idx = url.indexOf(marker)
  if (idx === -1) return null
  const path = url.slice(idx + marker.length)
  return path ? decodeURIComponent(path) : null
}

import 'server-only'
import { createClient } from '@supabase/supabase-js'

/**
 * Service-role Supabase client (US 4.4).
 *
 * Bypasses RLS, so it must ONLY be used in trusted server contexts (the
 * notification webhook route and the unsubscribe route) — never in a path
 * reachable with user-controlled intent without its own authorization check.
 *
 * Requires SUPABASE_SERVICE_ROLE_KEY, which must never be exposed to the client.
 */
export function createSupabaseAdminClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY

  if (!url || !serviceKey) {
    throw new Error(
      'Supabase admin client requires NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY',
    )
  }

  return createClient(url, serviceKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  })
}

/**
 * Supabase session refresh helper for Next.js middleware.
 *
 * Why this exists:
 *   Supabase's auth tokens are short-lived (1 hour by default). Without a
 *   refresh-on-every-request middleware, signed-in users would get logged out
 *   unexpectedly. This helper does three things:
 *     1. Reads the existing session cookie
 *     2. Calls supabase.auth.getUser() which auto-refreshes if needed
 *     3. Writes the (possibly refreshed) cookie back on the response
 *
 * It also enforces route protection — unauthenticated users hitting protected
 * routes are redirected to /login, and signed-in users hitting /login or /signup
 * are redirected to /lost.
 */
import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

// Routes that require a valid Supabase session
const PROTECTED_PREFIXES = ['/lost', '/found', '/messages', '/create', '/profile']

// Routes that should redirect signed-in users away (no point seeing login when logged in)
const AUTH_ROUTES = ['/login', '/signup']

export async function updateSession(request: NextRequest) {
  // Start with a "pass-through" response. We may overwrite cookies on it below.
  let supabaseResponse = NextResponse.next({ request })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          // Mirror cookie writes onto BOTH the request (so subsequent code in
          // this middleware sees them) and the response (so the browser receives them).
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          supabaseResponse = NextResponse.next({ request })
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options),
          )
        },
      },
    },
  )

  // IMPORTANT: do not run any code between createServerClient and getUser.
  // A simple mistake (e.g. an early return) makes the session fail to refresh
  // and users get randomly logged out.
  const {
    data: { user },
  } = await supabase.auth.getUser()

  const path = request.nextUrl.pathname
  const isProtected = PROTECTED_PREFIXES.some(
    (p) => path === p || path.startsWith(p + '/'),
  )
  const isAuthRoute = AUTH_ROUTES.includes(path)

  if (isProtected && !user) {
    const url = request.nextUrl.clone()
    url.pathname = '/login'
    return NextResponse.redirect(url)
  }

  if (isAuthRoute && user) {
    const url = request.nextUrl.clone()
    url.pathname = '/lost'
    return NextResponse.redirect(url)
  }

  return supabaseResponse
}

/**
 * Server-side Supabase client (Server Components, Server Actions, Route Handlers).
 *
 * Use this in any server file that needs the authenticated user — e.g. a page
 * that reads the current user's profile, or a server action that inserts into
 * `items` on behalf of the user.
 *
 * Cookies are read/written via Next.js's `cookies()` helper. Cookie writes can
 * fail in Server Components (Next.js disallows them outside actions/handlers);
 * we swallow that error because middleware will refresh the session anyway.
 */
import 'server-only'
import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'

export async function createSupabaseServerClient() {
  const cookieStore = await cookies()

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) => {
              cookieStore.set(name, value, options)
            })
          } catch {
            // The `setAll` method was called from a Server Component.
            // Server Components can't set cookies — middleware handles
            // session refresh, so it's safe to ignore here.
          }
        },
      },
    },
  )
}

'use client'

import {
  createContext,
  useCallback,
  useContext,
  useState,
  type ReactNode,
} from 'react'

interface UnreadContextValue {
  unreadCounts: Record<string, number>
  clearUnread: (conversationId: string) => void
  incrementUnread: (conversationId: string) => void
  totalUnread: number
}

const UnreadContext = createContext<UnreadContextValue | null>(null)

interface UnreadProviderProps {
  initialUnreadCounts: Record<string, number>
  children: ReactNode
}

export function UnreadProvider({ initialUnreadCounts, children }: UnreadProviderProps) {
  const [unreadCounts, setUnreadCounts] = useState<Record<string, number>>(
    () => ({ ...initialUnreadCounts }),
  )

  const totalUnread = Object.values(unreadCounts).reduce((sum, n) => sum + n, 0)

  const clearUnread = useCallback((conversationId: string) => {
    setUnreadCounts((prev) => ({ ...prev, [conversationId]: 0 }))
  }, [])

  const incrementUnread = useCallback((conversationId: string) => {
    setUnreadCounts((prev) => ({
      ...prev,
      [conversationId]: (prev[conversationId] ?? 0) + 1,
    }))
  }, [])

  return (
    <UnreadContext.Provider value={{ unreadCounts, clearUnread, incrementUnread, totalUnread }}>
      {children}
    </UnreadContext.Provider>
  )
}

export function useUnread(): UnreadContextValue {
  const ctx = useContext(UnreadContext)
  if (!ctx) throw new Error('useUnread must be used inside UnreadProvider')
  return ctx
}

'use client'

import { useEffect, useRef } from 'react'
import { createSupabaseBrowserClient } from '@/app/lib/supabase/client'
import type { MessageRow } from '@/app/lib/definitions'
import type { RealtimeChannel } from '@supabase/supabase-js'

interface UseRealtimeMessagesOptions {
  currentUserId: string
  onNewMessage: (message: MessageRow) => void
}

export function useRealtimeMessages({
  currentUserId,
  onNewMessage,
}: UseRealtimeMessagesOptions) {
  const callbackRef = useRef(onNewMessage)
  const supabaseRef = useRef(createSupabaseBrowserClient())

  useEffect(() => {
    callbackRef.current = onNewMessage
  }, [onNewMessage])

  useEffect(() => {
    const supabase = supabaseRef.current

    const channel: RealtimeChannel = supabase
      .channel(`messages-realtime-${currentUserId}`)
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'messages' },
        (payload) => {
          const msg = payload.new as MessageRow
          if (msg.sender_id !== currentUserId) {
            callbackRef.current(msg)
          }
        },
      )
      .subscribe((status, err) => {
        if (status === 'CHANNEL_ERROR') {
          console.error('[realtime] channel error:', err?.message)
        }
        if (status === 'TIMED_OUT') {
          console.warn('[realtime] subscription timed out for user', currentUserId)
        }
      })

    return () => {
      supabase.removeChannel(channel)
    }
  }, [currentUserId])
}

'use client'

/**
 * Light/dark theme hook.
 *
 * The actual theme lives as a `.dark` class on <html> (applied pre-hydration by
 * an inline script in app/layout.tsx, and toggled here). We read it via
 * useSyncExternalStore so it's SSR-safe and stays in sync across tabs without
 * any provider or set-state-in-effect.
 */

import { useSyncExternalStore, useCallback } from 'react'

export type Theme = 'light' | 'dark'

const STORAGE_KEY = 'slugfound-theme'
const THEME_EVENT = 'slugfound-themechange'

function subscribe(callback: () => void): () => void {
  window.addEventListener('storage', callback)
  window.addEventListener(THEME_EVENT, callback)
  return () => {
    window.removeEventListener('storage', callback)
    window.removeEventListener(THEME_EVENT, callback)
  }
}

function getSnapshot(): Theme {
  return document.documentElement.classList.contains('dark') ? 'dark' : 'light'
}

function getServerSnapshot(): Theme {
  return 'light'
}

export function useTheme(): { theme: Theme; toggleTheme: () => void } {
  const theme = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)

  const toggleTheme = useCallback(() => {
    const next: Theme = document.documentElement.classList.contains('dark') ? 'light' : 'dark'
    document.documentElement.classList.toggle('dark', next === 'dark')
    try {
      localStorage.setItem(STORAGE_KEY, next)
    } catch {
      // localStorage unavailable (private mode) — the class still applies for this session.
    }
    window.dispatchEvent(new Event(THEME_EVENT))
  }, [])

  return { theme, toggleTheme }
}
